INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aae191b5ffbbbfeb64c0295', 'https://physiciancareers.ca/jobs/physician-bipoc-specific-6aae191b5ffbbbfeb64c0295', 'Physician - BIPOC specific', 'Family Medicine', 'part-time', 'Planned Parenthood Toronto', 'north york', 'ON', '36 B Prince Arthur Avenue', 'Old Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-09-18', '2026-10-04', '2026-10-04', '2026-10-04', FALSE, '[]'::jsonb, '', 'JOB TITLE Physician, BIPOC Specific LOCATION: Downtown (36B Prince Arthur Ave) &amp; North York (940 Sheppard Ave West), SALARY $335,911.73 ($134,364.69 pro-rated to 0.4 FTE and inclusive of on-call stipend) FTE STATUS: 0.4 FTE REPORTING TO: Director of Community Health Services DURATION OF POSITION: Permanent Planned Parenthood Toronto (PPT) is a fully accredited community health centre that provides primary health care services to youth 13 to 29 years as well as health promotion programming, education, training and research to improve the health and well-being of equity-deserving youth in Toronto. We are currently seeking a racialized Physician to work 15 hours a week. In accordance to PPT’s anti-racist and equity principles, we particularly encourage applications from Black, Indigenous, and/or South Asian communities in order to better reflect the communities of youth we serve and the specific needs of racialized youth. POSITION OVERVIEW The Physician works within an interdisciplinary health care team to independently and collaboratively provide comprehensive primary and episodic health care to clients with an emphasis on sexual &amp; reproductive health, health promotion, disease prevention and health education. The Physician is a member of the Health Services Team and is responsible for supporting the agency&#39;s mission, values and objectives. The Physician also functions in accordance with relevant legislation and standards of medical practice. RESPONSIBILITIES • Performs assessment, diagnosis, treatment, health education/counselling and other medical functions as required according to the College of Physicians and Surgeons of Ontario standards of practice. • Provides virtual, over-the-phone and in-person client-centred care. • Manages and supports a client caseload. • Acts as primary liaison and consult with the Nurse Practitioners in assessment, diagnosis and treatment of clients. • Utilizes appropriate referral networks and agencies for clients. • Participates in chart reviews and case conferences. • Able to perform venipuncture and carry out related blood work. • Ensures that laboratory procedural forms are filled out correctly and that specimens are procured and handled properly. • Participates in the Centre’s on call service as directed. • Participates in developing, reviewing, and updating policies and procedures; has specific responsibility for developing medical protocols and procedures. • Provides Standard HIV Point of Care HIV counselling and testing to clients in accordance with the Ministry of Health Policies, Procedures and Quality Assurance for Point-of-Care HIV testing in Ontario. • Provides educational information on IUDs and able to perform IUD insertions and removals. • Provides educational information on the birth control implant and does implant insertions and removals (training can be provided) • Supports trans clients with gender affirming care, including hormone therapy and puberty suppression • Prescribe relevant medications and provide follow up care to clients requesting medical abortions at PPT • Maintains complete and accurate records of client visits including data required by Ontario Health and participates in regular quality of care chart audits and review. • Provides support in the development of Health Services protocols, and collects data and other appropriate administrative tasks as required. • Contributes to the planning and evaluation of Health Services programming and activities. QUALIFICATIONS • Medical degree from a recognized university • Licence to practice medicine and membership in good standing with the College of Physicians and Surgeons of Ontario • Three to five years primary care experience; preferably in a community health setting • The successful candidate will be Black, Indigenous and / or a person of colour. • Demonstrated ability to work with youth in areas of sexual and reproductive health, mental health, and gender-affirming care. • Proficiency and experience working with electronic health records an asset. • Demonstrated commitment to equity goals and principles, sexual and reproductive rights and to being youth positive, 2SLGBTQ positive, sex-positive, sex work positive and to being inclusive of diverse sexual and gender identities. • Commitment to pro-choice philosophy • Commitment to working from a community development perspective • Commitment to working cooperatively in a community-based setting as part of an inter-disciplinary team • Excellent written and verbal communication skills • Proficiency and experience working in a computerized environment', '{"Responsibilities":"• Performs assessment, diagnosis, treatment, health education/counselling and other medical functions as required according to the College of Physicians and Surgeons of Ontario standards of practice. • Provides virtual, over-the-phone and in-person client-centred care. • Manages and supports a client caseload. • Acts as primary liaison and consult with the Nurse Practitioners in assessment, diagnosis and treatment of clients. • Utilizes appropriate referral networks and agencies for clients. • Participates in chart reviews and case conferences. • Able to perform venipuncture and carry out related blood work. • Ensures that laboratory procedural forms are filled out correctly and that specimens are procured and handled properly. • Participates in the Centre’s on call service as directed. • Participates in developing, reviewing, and updating policies and procedures; has specific responsibility for developing medical protocols and procedures. • Provides Standard HIV Point of Care HIV counselling and testing to clients in accordance with the Ministry of Health Policies, Procedures and Quality Assurance for Point-of-Care HIV testing in Ontario. • Provides educational information on IUDs and able to perform IUD insertions and removals. • Provides educational information on the birth control implant and does implant insertions and removals (training can be provided) • Supports trans clients with gender affirming care, including hormone therapy and puberty suppression • Prescribe relevant medications and provide follow up care to clients requesting medical abortions at PPT • Maintains complete and accurate records of client visits including data required by Ontario Health and participates in regular quality of care chart audits and review. • Provides support in the development of Health Services protocols, and collects data and other appropriate administrative tasks as required. • Contributes to the planning and evaluation of Health Services programming and activities.","Qualifications":"• Medical degree from a recognized university • Licence to practice medicine and membership in good standing with the College of Physicians and Surgeons of Ontario • Three to five years primary care experience; preferably in a community health setting • The successful candidate will be Black, Indigenous and / or a person of colour. • Demonstrated ability to work with youth in areas of sexual and reproductive health, mental health, and gender-affirming care. • Proficiency and experience working with electronic health records an asset. • Demonstrated commitment to equity goals and principles, sexual and reproductive rights and to being youth positive, 2SLGBTQ positive, sex-positive, sex work positive and to being inclusive of diverse sexual and gender identities. • Commitment to pro-choice philosophy • Commitment to working from a community development perspective • Commitment to working cooperatively in a community-based setting as part of an inter-disciplinary team • Excellent written and verbal communication skills • Proficiency and experience working in a computerized environment"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Physician - BIPOC specific","description":"JOB TITLE Physician, BIPOC Specific LOCATION: Downtown (36B Prince Arthur Ave) &amp; North York (940 Sheppard Ave West), SALARY $335,911.73 ($134,364.69 pro-rated to 0.4 FTE and inclusive of on-call stipend) FTE STATUS: 0.4 FTE REPORTING TO: Director of Community Health Services DURATION OF POSITION: Permanent Planned Parenthood Toronto (PPT) is a fully accredited community health centre that provides primary health care services to youth 13 to 29 years as well as health promotion programming, education, training and research to improve the health and well-being of equity-deserving youth in Toronto. We are currently seeking a racialized Physician to work 15 hours a week. In accordance to PPT’s anti-racist and equity principles, we particularly encourage applications from Black, Indigenous, and/or South Asian communities in order to better reflect the communities of youth we serve and the specific needs of racialized youth. POSITION OVERVIEW The Physician works within an interdisciplinary health care team to independently and collaboratively provide comprehensive primary and episodic health care to clients with an emphasis on sexual &amp; reproductive health, health promotion, disease prevention and health education. The Physician is a member of the Health Services Team and is responsible for supporting the agency&#39;s mission, values and objectives. The Physician also functions in accordance with relevant legislation and standards of medical practice. RESPONSIBILITIES • Performs assessment, diagnosis, treatment, health education/counselling and other medical functions as required according to the College of Physicians and Surgeons of Ontario standards of practice. • Provides virtual, over-the-phone and in-person client-centred care. • Manages and supports a client caseload. • Acts as primary liaison and consult with the Nurse Practitioners in assessment, diagnosis and treatment of clients. • Utilizes appropriate referral networks and agencies for clients. • Participates in chart reviews and case conferences. • Able to perform venipuncture and carry out related blood work. • Ensures that laboratory procedural forms are filled out correctly and that specimens are procured and handled properly. • Participates in the Centre’s on call service as directed. • Participates in developing, reviewing, and updating policies and procedures; has specific responsibility for developing medical protocols and procedures. • Provides Standard HIV Point of Care HIV counselling and testing to clients in accordance with the Ministry of Health Policies, Procedures and Quality Assurance for Point-of-Care HIV testing in Ontario. • Provides educational information on IUDs and able to perform IUD insertions and removals. • Provides educational information on the birth control implant and does implant insertions and removals (training can be provided) • Supports trans clients with gender affirming care, including hormone therapy and puberty suppression • Prescribe relevant medications and provide follow up care to clients requesting medical abortions at PPT • Maintains complete and accurate records of client visits including data required by Ontario Health and participates in regular quality of care chart audits and review. • Provides support in the development of Health Services protocols, and collects data and other appropriate administrative tasks as required. • Contributes to the planning and evaluation of Health Services programming and activities. QUALIFICATIONS • Medical degree from a recognized university • Licence to practice medicine and membership in good standing with the College of Physicians and Surgeons of Ontario • Three to five years primary care experience; preferably in a community health setting • The successful candidate will be Black, Indigenous and / or a person of colour. • Demonstrated ability to work with youth in areas of sexual and reproductive health, mental health, and gender-affirming care. • Proficiency and experience working with electronic health records an asset. • Demonstrated commitment to equity goals and principles, sexual and reproductive rights and to being youth positive, 2SLGBTQ positive, sex-positive, sex work positive and to being inclusive of diverse sexual and gender identities. • Commitment to pro-choice philosophy • Commitment to working from a community development perspective • Commitment to working cooperatively in a community-based setting as part of an inter-disciplinary team • Excellent written and verbal communication skills • Proficiency and experience working in a computerized environment","datePosted":"2026-09-18T00:00:00.000Z","validThrough":"2026-10-04T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Planned Parenthood Toronto"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"36 B Prince Arthur Avenue","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M5R 1A9","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aae191b5ffbbbfeb64c0295"}}'::jsonb, '2026-10-04T05:13:17.157Z'
)
