INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aaa271d5ffbbbfeb64372e9', 'https://physiciancareers.ca/jobs/gp-psychotherapist400hour-net-virtual-only-part-time-6aaa271d5ffbbbfeb64372e9', '***GP Psychotherapist**~$400/hour NET. Virtual only. Part-time', 'Family Medicine', 'part-time', 'Institute for Behavioural & Functional Medicine', 'scarborough', 'ON', '3410 Sheppard Avenue East', 'Toronto, ON', 43.7764, -79.2318, 18.32, NULL, 'hourly', 400, 400, 400, 800000, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-09-15', '2026-10-24', '2026-10-24', '2026-10-24', FALSE, '[]'::jsonb, '', 'Key information on opportunity : • Virtual appointments only • Schedule is flexible (your choice) • Approximately 5-10 hours/week with opportunity to increase if you desire • No admin work, you just have to document your consultations • Billings: estimated billings up to $400/hour net to you (OHIP) Position Overview : We are looking for an GP Psychotherapist (Must have GP Focused Practice Designation in Psychotherapy by the MOHLTC-OMA committee) with excellent people skills to do depression/anxiety/PTSD consults for our patients. The purpose of these consultations will be to see if the patient is a good candidate for Group Counselling Sessions in mindfulness, CBT, CPT, CBT-i, etc. ( Group Counselling | Institute for Behavioural and Functional Medicine ) We are also looking for the physician to do CBT and/or CPT Group Counselling Sessions with patients. Time commitment : 5-10 hours per month. Opportunity to add more hours will likely be available if interested. Income : • Estimated billings $400/hour net to you (OHIP, no HST charged) Location : Virtual, appointments done over Zoom Healthcare. Hours : flexible Admin : Complete Admin support. No admin work - you just have to complete your notes (Accuro EMR) - several templates to choose from and can help you create your own. Extensive questionnaires are already completed prior to appointments to cut down on charting and we can help you create the ones you would like. Requirements : Licensed to practice medicine in Ontario. Must have GP Focused Practice Designation in Psychotherapy by the MOHLTC-OMA committee and be visible in the OMA directory. About the clinic : Institute for Behavioural &amp; Functional Medicine offers behavioural &amp; lifestyle interventions to help patients retrainng their physiology to correct chronic health problems. We offer patients evidence-based, OHIP-funded rehabilitation programs like CBT-i, CBT for headache, CBT for energy management and more. The first consultation is with the physician to evaluate for a patient&#39;s suitability for beginning psychological rehabilitation of their chronic condition. The 2nd appointment is with the GP Psychotherapist to prepare for the OHIP funded counselling. Learn more about this rapidly expanding field at ibfmed.ca .', '{"About":"the clinic : Institute for Behavioural &amp; Functional Medicine offers behavioural &amp; lifestyle interventions to help patients retrainng their physiology to correct chronic health problems. We offer patients evidence-based, OHIP-funded rehabilitation programs like CBT-i, CBT for headache, CBT for energy management and more. The first consultation is with the physician to evaluate for a patient&#39;s suitability for beginning psychological rehabilitation of their chronic condition. The 2nd appointment is with the GP Psychotherapist to prepare for the OHIP funded counselling. Learn more"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"***GP Psychotherapist**~$400/hour NET. Virtual only. Part-time","description":"Key information on opportunity : • Virtual appointments only • Schedule is flexible (your choice) • Approximately 5-10 hours/week with opportunity to increase if you desire • No admin work, you just have to document your consultations • Billings: estimated billings up to $400/hour net to you (OHIP) Position Overview : We are looking for an GP Psychotherapist (Must have GP Focused Practice Designation in Psychotherapy by the MOHLTC-OMA committee) with excellent people skills to do depression/anxiety/PTSD consults for our patients. The purpose of these consultations will be to see if the patient is a good candidate for Group Counselling Sessions in mindfulness, CBT, CPT, CBT-i, etc. ( Group Counselling | Institute for Behavioural and Functional Medicine ) We are also looking for the physician to do CBT and/or CPT Group Counselling Sessions with patients. Time commitment : 5-10 hours per month. Opportunity to add more hours will likely be available if interested. Income : • Estimated billings $400/hour net to you (OHIP, no HST charged) Location : Virtual, appointments done over Zoom Healthcare. Hours : flexible Admin : Complete Admin support. No admin work - you just have to complete your notes (Accuro EMR) - several templates to choose from and can help you create your own. Extensive questionnaires are already completed prior to appointments to cut down on charting and we can help you create the ones you would like. Requirements : Licensed to practice medicine in Ontario. Must have GP Focused Practice Designation in Psychotherapy by the MOHLTC-OMA committee and be visible in the OMA directory. About the clinic : Institute for Behavioural &amp; Functional Medicine offers behavioural &amp; lifestyle interventions to help patients retrainng their physiology to correct chronic health problems. We offer patients evidence-based, OHIP-funded rehabilitation programs like CBT-i, CBT for headache, CBT for energy management and more. The first consultation is with the physician to evaluate for a patient&#39;s suitability for beginning psychological rehabilitation of their chronic condition. The 2nd appointment is with the GP Psychotherapist to prepare for the OHIP funded counselling. Learn more about this rapidly expanding field at ibfmed.ca .","datePosted":"2026-09-15T00:00:00.000Z","validThrough":"2026-10-24T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Institute for Behavioural & Functional Medicine"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"3410 Sheppard Avenue East","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M1T3K4","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aaa271d5ffbbbfeb64372e9"}}'::jsonb, '2026-10-04T05:13:19.580Z'
)
