INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aa8d3e55ffbbbfeb63fe834', 'https://physiciancareers.ca/jobs/family-practice-walk-in-clinic-toronto-6aa8d3e55ffbbbfeb63fe834', 'Family Practice & Walk-In Clinic (Toronto)', 'Family Medicine', 'full-time', 'Pharmabest Medical Clinics', 'downtown toronto', 'ON', '1173 Queen Street West', 'Old Toronto, ON', 43.6532, -79.3832, 0, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, TRUE, FALSE, NULL, '2026-09-14', '2026-12-13', '2026-12-13', '2026-12-13', FALSE, '["pharmabestmedicalclinics@gmail.com"]'::jsonb, '', 'We are seeking a Family Physician join our growing team at our Toronto Clinic. We offer in-person family practice &amp; walk-in visits as well as telemedicine services across multiple clinics throughout Ontario. 1,600 sqft of dedicated practice space which is fully outfitted with 6 exam rooms. Existing practitioners already onsite. This is a high volume, high exposure clinic with an existing patient base. You will be busy from day one. What We Offer Competitive overhead with optional lease opportunities (flexible now and in the future) Managed practice opportunities with complete support including staffing, EMR, &amp; billing support Ability to join our clinic as a solo physician or collocate with a group of physicians Excellent reputation within the communities we serve Busy, accessible, and high-exposure locations Established network of medical clinics, family physicians, specialists and pharmacists Opportunities across the GTA &amp; Golden Horseshoe Open to local and international candidates (must hold a valid CPSO practice license) Spend less time managing your practice and more time caring for patients. If you are looking to start, expand, or relocate your practice to a more supportive environment, we would love to hear from you. To apply: Please send an e-mail to: pharmabestmedicalclinics@gmail.com Please include your CPSO number and CV. PharmaBest Medical Clinics — The right location. The right support. The right opportunity.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Family Practice & Walk-In Clinic (Toronto)","description":"We are seeking a Family Physician join our growing team at our Toronto Clinic. We offer in-person family practice &amp; walk-in visits as well as telemedicine services across multiple clinics throughout Ontario. 1,600 sqft of dedicated practice space which is fully outfitted with 6 exam rooms. Existing practitioners already onsite. This is a high volume, high exposure clinic with an existing patient base. You will be busy from day one. What We Offer Competitive overhead with optional lease opportunities (flexible now and in the future) Managed practice opportunities with complete support including staffing, EMR, &amp; billing support Ability to join our clinic as a solo physician or collocate with a group of physicians Excellent reputation within the communities we serve Busy, accessible, and high-exposure locations Established network of medical clinics, family physicians, specialists and pharmacists Opportunities across the GTA &amp; Golden Horseshoe Open to local and international candidates (must hold a valid CPSO practice license) Spend less time managing your practice and more time caring for patients. If you are looking to start, expand, or relocate your practice to a more supportive environment, we would love to hear from you. To apply: Please send an e-mail to: pharmabestmedicalclinics@gmail.com Please include your CPSO number and CV. PharmaBest Medical Clinics — The right location. The right support. The right opportunity.","datePosted":"2026-09-14T00:00:00.000Z","validThrough":"2026-12-13T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Pharmabest Medical Clinics"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1173 Queen Street West","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M6J 1J6","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa8d3e55ffbbbfeb63fe834"}}'::jsonb, '2026-10-04T05:13:21.316Z'
)
