INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aa8d3e45ffbbbfeb63fe819', 'https://physiciancareers.ca/jobs/physician-needed-for-tsdc-regular-or-relief-schedule-6aa8d3e45ffbbbfeb63fe819', 'Physician needed for TSDC (regular or relief schedule)', 'Family Medicine', 'part-time', 'Calian', 'etobicoke', 'ON', '169 Horner Ave', 'Toronto, ON', 43.6205, -79.5132, 11.08, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-09-14', '2026-10-23', '2026-10-23', '2026-10-23', FALSE, '[]'::jsonb, '', 'Position Overview Calian is currently seeking physicians to work at the Toronto South Detention Centre. Working within an interdisciplinary health care team, the Physician will provide primary care medical services to marginalized and diverse populations within a Toronto-based correctional facility housing patients with complex health issues such as urgent, acute, chronic care, addiction and mental health issues. Responsibilities • Performing physical examinations, review and document health records, diagnose and treat chronic and acute injuries and mental illness. • A focus on collaboration with health team leads, specialists and community health providers is key in this role. Your knowledge will contribute to evolving healthcare best practices. Qualifications • 5+ years of experience in a variety of practice settings including the following: in addictions treatment (including methadone and suboxone), in caring for patients from marginalized and diverse populations, in treating patients with mental health concerns, in providing urgent or acute care, in managing chronic and complex conditions, and in managing infectious diseases. • Registered for independent practice with the College of Physicians and Surgeons of Ontario • Valid OHIP billing number Additional Requirements • You must be able to obtain a Ministry of Ontario Security Clearance (which includes a new Vulnerable Sector Police Check) Compensation Based on skills and experience Vacancy We have 2 available positions', '{"Responsibilities":"• Performing physical examinations, review and document health records, diagnose and treat chronic and acute injuries and mental illness. • A focus on collaboration with health team leads, specialists and community health providers is key in this role. Your knowledge will contribute to evolving healthcare best practices.","Qualifications":"• 5+ years of experience in a variety of practice settings including the following: in addictions treatment (including methadone and suboxone), in caring for patients from marginalized and diverse populations, in treating patients with mental health concerns, in providing urgent or acute care, in managing chronic and complex conditions, and in managing infectious diseases. • Registered for independent practice with the College of Physicians and Surgeons of Ontario • Valid OHIP billing number Additional Requirements • You must be able to obtain a Ministry of Ontario Security Clearance (which includes a new Vulnerable Sector Police Check) Compensation Based on skills and experience Vacancy We have 2 available positions"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Physician needed for TSDC (regular or relief schedule)","description":"Position Overview Calian is currently seeking physicians to work at the Toronto South Detention Centre. Working within an interdisciplinary health care team, the Physician will provide primary care medical services to marginalized and diverse populations within a Toronto-based correctional facility housing patients with complex health issues such as urgent, acute, chronic care, addiction and mental health issues. Responsibilities • Performing physical examinations, review and document health records, diagnose and treat chronic and acute injuries and mental illness. • A focus on collaboration with health team leads, specialists and community health providers is key in this role. Your knowledge will contribute to evolving healthcare best practices. Qualifications • 5+ years of experience in a variety of practice settings including the following: in addictions treatment (including methadone and suboxone), in caring for patients from marginalized and diverse populations, in treating patients with mental health concerns, in providing urgent or acute care, in managing chronic and complex conditions, and in managing infectious diseases. • Registered for independent practice with the College of Physicians and Surgeons of Ontario • Valid OHIP billing number Additional Requirements • You must be able to obtain a Ministry of Ontario Security Clearance (which includes a new Vulnerable Sector Police Check) Compensation Based on skills and experience Vacancy We have 2 available positions","datePosted":"2026-09-14T00:00:00.000Z","validThrough":"2026-10-23T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Calian"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"169 Horner Ave","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M8Z0C2","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa8d3e45ffbbbfeb63fe819"}}'::jsonb, '2026-10-04T05:13:22.395Z'
)
