INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aa8d3e45ffbbbfeb63fe77f', 'https://physiciancareers.ca/jobs/primary-care-physician-needed-for-cfb-toronto-no-evenings-or-weekends-6aa8d3e45ffbbbfeb63fe77f', 'Primary Care Physician needed for CFB Toronto - no evenings or weekends!', 'Family Medicine', 'part-time', 'Calian', 'north york', 'ON', '1 Yukon Lane', 'Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, NULL, '2026-09-14', '2026-10-09', '2026-10-09', '2026-10-09', FALSE, '["paisley.letourneau@calian.com"]'::jsonb, '', 'Calian is proud to continue a long-standing contractual relationship with the Department of National Defence (DND) to provide healthcare services to the Canadian Armed Forces. Through the Health Care Provider Contract, Calian employs health care professionals across Canada who are integral to supporting the health and wellbeing of our military members. Position Overview Calian is seeking a Primary Care Physician to join the dynamic health team at CFB Toronto near Downsview. Enjoy this modern, multidisciplinary clinic with diagnostics and labs on-site, fostering a collaborative and rewarding environment. Serving a unique and engaged patient population who are committed to their care. A refreshing change of pace from high-volume environments, where quality of care is prioritized over quantity. Physicians can expect a work/life balance, generous appointment times with patients and no overhead costs. Responsibilities • Perform comprehensive health assessments and synthesize data to make medical diagnoses. • Initiate and manage the care of patients within scope of practice, including monitoring therapy of patients with chronic stable illnesses. • Implement strategies to promote health and prevent illness. • Conduct periodic health examinations and determine patient fitness for duty. • Make appropriate medical employment limitation (MEL) recommendations. • Provide diagnosis and treatment of occupational and environmental injuries and illnesses, including rehabilitation. • Maintain occupational health records through the Electronic Health Record system and other forms. • Refer patients to other healthcare providers when warranted. • Collaborate with an interdisciplinary team to ensure patients’ healthcare needs are met. Advantages of this Environment • Regular weekday hours (7:30 am – 4:00 pm, Monday–Friday) • Generous allotment of time for each patient, and built in admin time • Guaranteed hourly rate with no overhead or clinic fees • Access to onsite allied health services including pharmacy, laboratory, physiotherapy, and mental health Qualifications • Licensed and in good standing with the College of Physicians and Surgeons in the location of practice • Certification in Family Medicine with the College of Family Physicians of Canada (CCFP) • Basic Life Support for Health Providers or CPR/AED Level C Certification • Minimum of one year of full-time equivalent experience providing patient medical care in primary care, occupational medicine, urgent care, or emergency medicine. New graduates may be considered. Additional Requirements • Ability to obtain a Government Security Clearance at the Reliability level • CF Basic Aviation and Dive Medicine Certification is considered an asset but not mandatory Interested in learning more? Reach out to Paisley! paisley.letourneau@calian.com', '{"Responsibilities":"• Perform comprehensive health assessments and synthesize data to make medical diagnoses. • Initiate and manage the care of patients within scope of practice, including monitoring therapy of patients with chronic stable illnesses. • Implement strategies to promote health and prevent illness. • Conduct periodic health examinations and determine patient fitness for duty. • Make appropriate medical employment limitation (MEL) recommendations. • Provide diagnosis and treatment of occupational and environmental injuries and illnesses, including rehabilitation. • Maintain occupational health records through the Electronic Health Record system and other forms. • Refer patients to other healthcare providers when warranted. • Collaborate with an interdisciplinary team to ensure patients’ healthcare needs are met. Advantages of this Environment • Regular weekday hours (7:30 am – 4:00 pm, Monday–Friday) • Generous allotment of time for each patient, and built in admin time • Guaranteed hourly rate with no overhead or clinic fees • Access to onsite allied health services including pharmacy, laboratory, physiotherapy, and mental health","Qualifications":"• Licensed and in good standing with the College of Physicians and Surgeons in the location of practice • Certification in Family Medicine with the College of Family Physicians of Canada (CCFP) • Basic Life Support for Health Providers or CPR/AED Level C Certification • Minimum of one year of full-time equivalent experience providing patient medical care in primary care, occupational medicine, urgent care, or emergency medicine. New graduates may be considered. Additional Requirements • Ability to obtain a Government Security Clearance at the Reliability level • CF Basic Aviation and Dive Medicine Certification is considered an asset but not mandatory Interested in learning more? Reach out to Paisley! paisley.letourneau@calian.com"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Primary Care Physician needed for CFB Toronto - no evenings or weekends!","description":"Calian is proud to continue a long-standing contractual relationship with the Department of National Defence (DND) to provide healthcare services to the Canadian Armed Forces. Through the Health Care Provider Contract, Calian employs health care professionals across Canada who are integral to supporting the health and wellbeing of our military members. Position Overview Calian is seeking a Primary Care Physician to join the dynamic health team at CFB Toronto near Downsview. Enjoy this modern, multidisciplinary clinic with diagnostics and labs on-site, fostering a collaborative and rewarding environment. Serving a unique and engaged patient population who are committed to their care. A refreshing change of pace from high-volume environments, where quality of care is prioritized over quantity. Physicians can expect a work/life balance, generous appointment times with patients and no overhead costs. Responsibilities • Perform comprehensive health assessments and synthesize data to make medical diagnoses. • Initiate and manage the care of patients within scope of practice, including monitoring therapy of patients with chronic stable illnesses. • Implement strategies to promote health and prevent illness. • Conduct periodic health examinations and determine patient fitness for duty. • Make appropriate medical employment limitation (MEL) recommendations. • Provide diagnosis and treatment of occupational and environmental injuries and illnesses, including rehabilitation. • Maintain occupational health records through the Electronic Health Record system and other forms. • Refer patients to other healthcare providers when warranted. • Collaborate with an interdisciplinary team to ensure patients’ healthcare needs are met. Advantages of this Environment • Regular weekday hours (7:30 am – 4:00 pm, Monday–Friday) • Generous allotment of time for each patient, and built in admin time • Guaranteed hourly rate with no overhead or clinic fees • Access to onsite allied health services including pharmacy, laboratory, physiotherapy, and mental health Qualifications • Licensed and in good standing with the College of Physicians and Surgeons in the location of practice • Certification in Family Medicine with the College of Family Physicians of Canada (CCFP) • Basic Life Support for Health Providers or CPR/AED Level C Certification • Minimum of one year of full-time equivalent experience providing patient medical care in primary care, occupational medicine, urgent care, or emergency medicine. New graduates may be considered. Additional Requirements • Ability to obtain a Government Security Clearance at the Reliability level • CF Basic Aviation and Dive Medicine Certification is considered an asset but not mandatory Interested in learning more? Reach out to Paisley! paisley.letourneau@calian.com","datePosted":"2026-09-14T00:00:00.000Z","validThrough":"2026-10-09T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Calian"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1 Yukon Lane","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M3K2C3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa8d3e45ffbbbfeb63fe77f"}}'::jsonb, '2026-10-04T05:13:23.869Z'
)
