  '6aa7811a5ffbbbfeb63d176d', 'https://physiciancareers.ca/jobs/family-medicine-locum-in-north-york-6aa7811a5ffbbbfeb63d176d', 'Family Medicine Locum in North York', 'Family Medicine', 'locum', 'ProHealth Medical Clinic', 'north york', 'ON', '403-1100 Sheppard Ave.', 'Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'daily', 1000, 1000, 1000, 220000, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-09-13', '2026-12-11', '2026-12-11', '2026-12-11', FALSE, '["dhsu@prohealthmedical.ca","heidilam@prohealthmedical.ca"]'::jsonb, '', 'looking for a Mandarin speaking Family Medicine Locum in North York/Sheppard starting anytime in 2026 Spoken Mandarin would be very beneficial but Cantonese also acceptable Roster of 2000+ patients Full admin team and nurse support who can speak English, Mandarin and Cantonese to serve patients. Nurse and admin team assist patient measurements, vitals and vaccines. Compensation will be $1000 per day 100% 3rd party billing 100% shadow billing Please directly contact Dr. Hsu at dhsu@prohealthmedical.ca and Ms. Heidi Lam at heidilam@prohealthmedical.ca if interested.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Family Medicine Locum in North York","description":"looking for a Mandarin speaking Family Medicine Locum in North York/Sheppard starting anytime in 2026 Spoken Mandarin would be very beneficial but Cantonese also acceptable Roster of 2000+ patients Full admin team and nurse support who can speak English, Mandarin and Cantonese to serve patients. Nurse and admin team assist patient measurements, vitals and vaccines. Compensation will be $1000 per day 100% 3rd party billing 100% shadow billing Please directly contact Dr. Hsu at dhsu@prohealthmedical.ca and Ms. Heidi Lam at heidilam@prohealthmedical.ca if interested.","datePosted":"2026-09-13T00:00:00.000Z","validThrough":"2026-12-11T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"ProHealth Medical Clinic"},"employmentType":"locum","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"403-1100 Sheppard Ave.","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M2K2W1","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa7811a5ffbbbfeb63d176d"}}'::jsonb, '2026-10-04T05:13:25.172Z'
)
