  '6a21088b76abc2c85ce3f011', 'https://physiciancareers.ca/jobs/toronto-walkin-shifts-family-practice-fho-is-ccm-new-grads-6a21088b76abc2c85ce3f011', 'TORONTO WALKIN SHIFTS, FAMILY PRACTICE, FHO IS, CCM NEW GRADS', 'Family Medicine', 'full-time', 'City Family Doctor Clinic (CFDC)', 'bloor', 'ON', '366 Bloor Street East', 'Old Toronto, ON', 43.6685, -79.39, 1.79, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-09-12', '2026-12-11', '2026-12-11', '2026-12-11', FALSE, '["elena@vamcomp.com"]'::jsonb, '', 'Medical Clinic Walk-in &amp; Family Practice at Sherbourne &amp; Bloor East seeking Part-Time and Full-Time Physicians for walk-in shifts , available 7 days a week . FHO: 2 spots available for eligible candidates. Family Physicians: Opportunity to start a new practice (CCM, FHG) or relocate an existing practice (solo or small group of 1–2 physicians or specialists). New Graduates and International Medical Graduates are welcome to apply (LMIA available for suitable candidates) EMR: OSCAR PRO Support Staff: Highly trained medical team assisting with injections, phlebotomy, rapid tests, and vital signs. Onsite Pharmacy Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"TORONTO WALKIN SHIFTS, FAMILY PRACTICE, FHO IS, CCM NEW GRADS","description":"Medical Clinic Walk-in &amp; Family Practice at Sherbourne &amp; Bloor East seeking Part-Time and Full-Time Physicians for walk-in shifts , available 7 days a week . FHO: 2 spots available for eligible candidates. Family Physicians: Opportunity to start a new practice (CCM, FHG) or relocate an existing practice (solo or small group of 1–2 physicians or specialists). New Graduates and International Medical Graduates are welcome to apply (LMIA available for suitable candidates) EMR: OSCAR PRO Support Staff: Highly trained medical team assisting with injections, phlebotomy, rapid tests, and vital signs. Onsite Pharmacy Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com","datePosted":"2026-09-12T00:00:00.000Z","validThrough":"2026-12-11T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"City Family Doctor Clinic (CFDC)"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"366 Bloor Street East","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M4W","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a21088b76abc2c85ce3f011"}}'::jsonb, '2026-10-04T05:13:26.372Z'
)
