  '69f192fd58d0b1387d81e694', 'https://physiciancareers.ca/jobs/toronto-immediate-walkin-shifts-family-practice-fho-is-ccm-new-grads-69f192fd58d0b1387d81e694', 'TORONTO IMMEDIATE WALKIN SHIFTS, FAMILY PRACTICE FHO IS, CCM NEW GRADS', 'Family Medicine', 'full-time', 'Davisville Medical Clinic', 'davisville', 'ON', 'Unit 4-1901 Yonge Street', 'Toronto, ON', 43.7011, -79.3971, 5.44, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-09-12', '2026-12-11', '2026-12-11', '2026-12-11', FALSE, '["elena@vamcomp.com"]'::jsonb, '', 'Busy Medical Clinic – Multiple Settings (Walk-in &amp; Family Practice) at Yonge &amp; Davisville currently seeking Family Physicians and Part-Time and Full-Time Physicians for immediate walk-in shifts , available 7 days a week . FHO: 2 positions available for eligible candidates. Family Physicians welcome to start a new practice (CCM, FHG) or relocate an existing practice (individuals or small groups of 1–2 physicians or specialists). New Graduates and International Medical Graduates are encouraged to apply (LMIA available for suitable candidates). EMR: OSCAR PRO Support Staff: Highly trained medical assistants provide support with injections, phlebotomy, rapid testing, and vital signs. Onsite Services: Pharmacy and Home Healthcare are on-site. A new clinic wing at the corner of Yonge &amp; Davisville (street level) is opening in 2026-2027 , offering relocation opportunities for a new group of physicians to join the existing team (FHO, FHG, CCM models). Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"TORONTO IMMEDIATE WALKIN SHIFTS, FAMILY PRACTICE FHO IS, CCM NEW GRADS","description":"Busy Medical Clinic – Multiple Settings (Walk-in &amp; Family Practice) at Yonge &amp; Davisville currently seeking Family Physicians and Part-Time and Full-Time Physicians for immediate walk-in shifts , available 7 days a week . FHO: 2 positions available for eligible candidates. Family Physicians welcome to start a new practice (CCM, FHG) or relocate an existing practice (individuals or small groups of 1–2 physicians or specialists). New Graduates and International Medical Graduates are encouraged to apply (LMIA available for suitable candidates). EMR: OSCAR PRO Support Staff: Highly trained medical assistants provide support with injections, phlebotomy, rapid testing, and vital signs. Onsite Services: Pharmacy and Home Healthcare are on-site. A new clinic wing at the corner of Yonge &amp; Davisville (street level) is opening in 2026-2027 , offering relocation opportunities for a new group of physicians to join the existing team (FHO, FHG, CCM models). Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com","datePosted":"2026-09-12T00:00:00.000Z","validThrough":"2026-12-11T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Davisville Medical Clinic"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"Unit 4-1901 Yonge Street","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M4S1Y6","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"69f192fd58d0b1387d81e694"}}'::jsonb, '2026-10-04T05:13:28.540Z'
