  '69c36e46db676bd89872247e', 'https://physiciancareers.ca/jobs/fho-toronto-dowtown-looking-for-guaranteed-wage-candidates-69c36e46db676bd89872247e', 'FHO TORONTO DOWTOWN LOOKING FOR GUARANTEED WAGE CANDIDATES', 'Family Medicine', 'full-time', 'Parliament Medical Clinic', 'midtown', 'ON', '595 Parliament St.', 'Toronto, ON', 43.7001, -79.397, 5.33, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-09-12', '2026-12-11', '2026-12-11', '2026-12-11', FALSE, '["elena@vamcomp.com"]'::jsonb, '', 'Parliament Medical Clinic looking for full time Doctor Family practice/ Walkin position starting September - October 2026. Remuneration based on guaranteed pay first few months with possibility to join FHO PLUS or CCM. Clinic located in very busy patient&#39;s flow traffic area. Excellent experienced medical administration. Possibility for extra Walkin shifts in midtown satellite clinics. For IMG doctors C10 is available. Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com', '{"Remuneration":"based on guaranteed pay first few months with possibility to join FHO PLUS or CCM. Clinic located in very busy patient&#39;s flow traffic area. Excellent experienced medical administration. Possibility for extra Walkin shifts in midtown satellite clinics. For IMG doctors C10 is available. Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"FHO TORONTO DOWTOWN LOOKING FOR GUARANTEED WAGE CANDIDATES","description":"Parliament Medical Clinic looking for full time Doctor Family practice/ Walkin position starting September - October 2026. Remuneration based on guaranteed pay first few months with possibility to join FHO PLUS or CCM. Clinic located in very busy patient&#39;s flow traffic area. Excellent experienced medical administration. Possibility for extra Walkin shifts in midtown satellite clinics. For IMG doctors C10 is available. Please contact our clinical coordinator at (416) 624-4641 or elena@vamcomp.com","datePosted":"2026-09-12T00:00:00.000Z","validThrough":"2026-12-11T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Parliament Medical Clinic"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"595 Parliament St.","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M4X1P9","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"69c36e46db676bd89872247e"}}'::jsonb, '2026-10-04T05:13:29.609Z'
