INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aa4df535ffbbbfeb637f666', 'https://physiciancareers.ca/jobs/looking-for-family-physician-with-womens-health-focus-6aa4df535ffbbbfeb637f666', 'Looking For Family Physician with Women''s Health Focus', 'Family Medicine', 'full-time', 'Regal Heights Medical Centre', 'downtown toronto', 'ON', '1086 St. Clair Ave W', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-09-11', '2026-10-30', '2026-10-30', '2026-10-30', FALSE, '[]'::jsonb, '', 'NEW AND MODERN MEDICAL CENTRE IN THE REGAL HEIGHTS AREA OF TORONTO SEEKING PART TIME / FULL-TIME FAMILY PHYSICIAN WITH WOMEN&#39;S HEALTH FOCUS NEW GRADS WELCOME Job Title : Family Medicine Physician Location: Toronto, ON Company: Regal Heights Medical Centre About Us: Regal Heights Medical Centre is a brand new medical centre that is physician-owned near Dufferin and St. Clair Ave West, Toronto that opened February 2025. We are dedicated to providing exceptional healthcare services to individuals and families in Regal Heights and all surrounding communities. We offer a wide range of medical services, including family medicine and specialty medicine, pharmacy services, and walk-in all under one roof. Our mission is to deliver personalized, compassionate care in a comfortable, modern and welcoming environment. Position Overview: As a Family Medicine Physician with a focus on Women’s Health, you will play an important role in delivering comprehensive, patient-centred care across the various stages of a woman’s life. The position will have a particular emphasis on preventive women’s health, perimenopause and menopause care, reproductive and sexual health, and age-appropriate screening. You will be supported by an experienced administrative and clinical team to ensure cohesive and seamless clinic operations. You will also have the opportunity to collaborate with other physicians, pharmacists, specialists, and allied healthcare professionals to provide coordinated and comprehensive care. This position is well suited to a Family Physician with a particular interest in women’s health who is looking to develop or expand this area of practice within a busy and growing medical centre. Responsibilities: Provide comprehensive primary care with a particular focus on women’s health across the lifespan. Assess and manage perimenopausal and menopausal concerns, including vasomotor symptoms, sleep disturbance, mood changes, genitourinary symptoms, bone health, cardiovascular risk, and discussion of appropriate treatment options. Provide routine women’s health screening and preventive care, including cervical cancer screening, breast cancer screening, osteoporosis risk assessment, cardiovascular risk assessment, and other age-appropriate investigations. Provide reproductive and sexual health care, including contraception counselling, preconception counselling, menstrual concerns, fertility-related concerns, and sexually transmitted infection screening and prevention. Assess and manage common gynecologic concerns, including abnormal uterine bleeding, pelvic pain, vaginal and vulvar symptoms, recurrent urinary concerns, and menstrual irregularities. Provide preventive care, health maintenance, lifestyle counselling, and patient education tailored to women at different stages of life. Diagnose and manage acute and chronic medical conditions within the scope of family medicine. Develop individualized treatment plans in collaboration with patients, incorporating their health goals, preferences, and risk factors. Coordinate referrals and investigations with gynecology, endocrinology, breast imaging, fertility services, osteoporosis clinics, and other specialists as appropriate. Utilize the ACCURO EMR system to document patient encounters, review investigations, and maintain comprehensive medical records. Participate in quality improvement initiatives and adhere to evidence-based clinical guidelines, screening recommendations, and best practices. Qualifications: -Medical degree from an accredited medical school. -Board certification in Family Medicine. -Completion of residency training in Family Medicine. -Valid medical license in Ontario. -Strong clinical skills and knowledge of evidence-based medical practices. -Excellent communication, interpersonal, and teamwork skills. -Commitment to providing high-quality, patient-centered care. -Ability to thrive in a fast-paced, collaborative environment. -Willingness to participate in continuing medical education and professional development activities. Benefits: -Very competitive overhead offered: 23% (no HST) - Incentive of $5000 sign-on bonus for 1-year term with additional retention bonuses annually. Please inquire for more details. -Opportunity to work in a new, modern medical centre complete with full staff breakroom with coffee and snacks - Opportunity to form a FHG with option to transition to FHO+ -Supportive work environment Regal Heights Medical Centre is an equal opportunity employer and welcomes applicants from diverse backgrounds. We thank all applicants for their interest; however, only those selected for an interview will be contacted. Join us in making a difference in the lives of our patients and community! We look forward to welcoming you to our team at Regal Heights Medical Centre.', '{"About":"Us: Regal Heights Medical Centre is a brand new medical centre that is physician-owned near Dufferin and St. Clair Ave West, Toronto that opened February 2025. We are dedicated to providing exceptional healthcare services to individuals and families in Regal Heights and all surrounding communities. We offer a wide range of medical services, including family medicine and specialty medicine, pharmacy services, and walk-in all under one roof. Our mission is to deliver personalized, compassionate care in a comfortable, modern and welcoming environment. Position Overview: As a Family Medicine Physician with a focus on Women’s Health, you will play an important role in delivering comprehensive, patient-centred care across the various stages of a woman’s life. The position will have a particular emphasis on preventive women’s health, perimenopause and menopause care, reproductive and sexual health, and age-appropriate screening. You will be supported by an experienced administrative and clinical team to ensure cohesive and seamless clinic operations. You will also have the opportunity to collaborate with other physicians, pharmacists, specialists, and allied healthcare professionals to provide coordinated and comprehensive care. This position is well suited to a Family Physician with a particular interest in women’s health who is looking to develop or expand this area of practice within a busy and growing medical centre.","Responsibilities":"Provide comprehensive primary care with a particular focus on women’s health across the lifespan. Assess and manage perimenopausal and menopausal concerns, including vasomotor symptoms, sleep disturbance, mood changes, genitourinary symptoms, bone health, cardiovascular risk, and discussion of appropriate treatment options. Provide routine women’s health screening and preventive care, including cervical cancer screening, breast cancer screening, osteoporosis risk assessment, cardiovascular risk assessment, and other age-appropriate investigations. Provide reproductive and sexual health care, including contraception counselling, preconception counselling, menstrual concerns, fertility-related concerns, and sexually transmitted infection screening and prevention. Assess and manage common gynecologic concerns, including abnormal uterine bleeding, pelvic pain, vaginal and vulvar symptoms, recurrent urinary concerns, and menstrual irregularities. Provide preventive care, health maintenance, lifestyle counselling, and patient education tailored to women at different stages of life. Diagnose and manage acute and chronic medical conditions within the s