INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a4ddcc0a641db6c310c562c', 'https://physiciancareers.ca/jobs/family-physician-established-large-pt-databasepartnership-equity-option-6a4ddcc0a641db6c310c562c', 'Family Physician-Established Large Pt Database(Partnership & Equity Option)', 'Family Medicine', 'full-time', 'FORT YORK MEDICAL CLINIC', 'york', 'ON', '219 fort York Boulevard', 'Toronto, ON', 43.6896, -79.4542, 7, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, TRUE, TRUE, FALSE, NULL, '2026-09-10', '2026-10-31', '2026-10-31', '2026-10-31', FALSE, '["contact@fortyorkmedical.com"]'::jsonb, '', 'Family Physician – Partnership &amp; Equity Opportunity Fort York Medical Clinic | Downtown Toronto (Bathurst &amp; Lakeshore) The Opportunity Join Fort York Medical and step into the perfect intersection of a fulfilling clinical practice, true work-life balance, and a clear, lucrative pathway to corporate partnership and equity. Located at the highly sought-after intersection of Bathurst and Lakeshore, our clinic is surrounded by over 20,000 residential condominium units with no direct primary care competitors in close proximity. Supported by an on-site pharmacy and a premier administrative team, an incoming physician will immediately tap into a massive, built-in patient base driven by our extensive internal roster of 26,000 patient charts and a highly active online waitlist. The Clinical Profile: High Yield, Low Friction You might wonder how sustaining a volume of 40 to 50 visits per day is feasible without clinical or administrative burnout. The answer lies in our highly favorable patient demographic and our tech-enabled infrastructure. Favorable Demographic: Our core patient base consists of young professionals aged 20 to 50. Efficient Workflow: The walk-in volume is fast-paced and highly efficient, consisting mostly of straightforward diagnostics (UTIs, URTIs, STIs/STDs), medication renewals, men&#39;s and women&#39;s health, weight management, musculoskeletal issues, and standard blood work or DI requisitions. The remaining volume allows you to focus heavily on comprehensive chronic disease management. Streamlined Scope: To keep the clinical day completely streamlined and low-friction, we operate with a strict no narcotics policy. The Infrastructure: Zero Administrative Burden Tech-Enabled Charting: Our entire ecosystem runs on Accuro EMR, fully integrated with Heidi AI to automate your clinical notes and drastically reduce screen time. Zero-Friction Intake: All intake forms and procedural waivers are processed via Ocean and completed by patients before they step into the exam room. External Referral Capture: We utilize Ocean eReferral to effortlessly capture and route inbound consults directly to your schedule. Elite Clinical Support: You are supported by highly trained clinical assistants and MOAs who manage all patient flow, lab pickups, vaccination, minor procedures, and e-lab result routing. Maximized Yield: You will have a dedicated billing specialist assigned to your practice, ensuring an OHIP rejection rate of less than 1%. What We Offer Ownership Potential: Immediate opportunities to transition into a partnership role with equity in the medical clinic. Ultimate Flexibility: Design a schedule that fits your lifestyle, complete with the flexibility to incorporate hybrid/virtual care days into your weekly rotation. Private Workspace: Work from a dedicated, private office that serves as your personalized, quiet hub for charting and virtual care, alongside full access to three state-of-the-art examination rooms. Comprehensive Transition Support: We actively welcome new Canadian graduates as well as internationally trained physicians (UK). We provide complete, wrap-around support including LMIA processing, Professional Medicine Corporation setup, accounting services, and real estate transition assistance. Premium Convenience: Reserved on-site parking available exclusively for our physicians. Qualifications Valid independent practice license (or soon-to-be licensed) with the College of Physicians and Surgeons of Ontario (CPSO). Certification in Family Medicine and membership with the College of Family Physicians of Canada (CFPC). Completed Medical Degree (MD) and Family Medicine residency. Legally eligible to work in Canada (Citizen, PR, or valid work permit). How to Apply Forward your CV along with a brief cover letter to: contact@fortyorkmedical.com For a confidential discussion or to inquire further about the clinical workflow and equity structure, text: 416-989-9909', '{"About":"the clinical workflow and equity structure, text: 416-989-9909","Qualifications":"Valid independent practice license (or soon-to-be licensed) with the College of Physicians and Surgeons of Ontario (CPSO). Certification in Family Medicine and membership with the College of Family Physicians of Canada (CFPC). Completed Medical Degree (MD) and Family Medicine residency. Legally eligible to work in Canada (Citizen, PR, or valid work permit). How to Apply Forward your CV along with a brief cover letter to: contact@fortyorkmedical.com For a confidential discussion or to inquire further"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Family Physician-Established Large Pt Database(Partnership & Equity Option)","description":"Family Physician – Partnership &amp; Equity Opportunity Fort York Medical Clinic | Downtown Toronto (Bathurst &amp; Lakeshore) The Opportunity Join Fort York Medical and step into the perfect intersection of a fulfilling clinical practice, true work-life balance, and a clear, lucrative pathway to corporate partnership and equity. Located at the highly sought-after intersection of Bathurst and Lakeshore, our clinic is surrounded by over 20,000 residential condominium units with no direct primary care competitors in close proximity. Supported by an on-site pharmacy and a premier administrative team, an incoming physician will immediately tap into a massive, built-in patient base driven by our extensive internal roster of 26,000 patient charts and a highly active online waitlist. The Clinical Profile: High Yield, Low Friction You might wonder how sustaining a volume of 40 to 50 visits per day is feasible without clinical or administrative burnout. The answer lies in our highly favorable patient demographic and our tech-enabled infrastructure. Favorable Demographic: Our core patient base consists of young professionals aged 20 to 50. Efficient Workflow: The walk-in volume is fast-paced and highly efficient, consisting mostly of straightforward diagnostics (UTIs, URTIs, STIs/STDs), medication renewals, men&#39;s and women&#39;s health, weight management, musculoskeletal issues, and standard blood work or DI requisitions. The remaining volume allows you to focus heavily on comprehensive chronic disease management. Streamlined Scope: To keep the clinical day completely streamlined and low-friction, we operate with a strict no narcotics policy. The Infrastructure: Zero Administrative Burden Tech-Enabled Charting: Our entire ecosystem runs on Accuro EMR, fully integrated with Heidi AI to automate your clinical notes and drastically reduce screen time. Zero-Friction Intake: All intake forms and procedural waivers are processed via Ocean and completed by patients before they step into the exam room. External Referral Capture: We utilize Ocean eReferral to effortlessly capture and route inbound consults directly to your schedule. Elite Clinical Support: You are supported by highly trained clinical assistants and MOAs who manage all patient flow, lab pickups, vaccination, minor procedures, and e-lab result routing. Maximized Yield: You will have a dedicated billing specialist assigned to your practice, ensuring an OHIP rejection rate of less than 1%. What We Offer Ownership Potential: Immediate opportunities to transition into a partnership role with equity in the medical clinic. Ultimate Flexibility: Design a schedule that fits your lifestyle, complete with the flexibility to incorporate hybrid/virtual care days into your weekly rotation. Private Workspace: Work from a dedicated, private office that serves as your personalized, quiet hub for charting and virtual care, alongside full access to three state-of-the-art examination rooms. Comprehensive Transition Support: We actively welcome new Canadian graduates as well as internationally trained physicians (UK). We provide complete, wrap-around support including LMIA processing, Professional Medicine Corporation setup, accounting services, and real estate transition assistance. Premium Convenience: Reserved on-site parking available exclusively for our physicians. Qualifications Valid independent practice license (or soon-to-be licensed) with the College of Physicians and Surgeons of Ontario (CPSO). Certification in Family Medicine and membership with the College of Family Physicians of Canada (CFPC). Completed Medical Degree (MD) and Family Medicine residency. Legally eligible to work in Canada (Citizen, PR, or valid work permit). How to Apply Forward your CV along with a brief cover letter to: contact@fortyorkmedical.com For a confidential discussion or to inquire further about the clinical workflow and equity structure, text: 416-989-9909","datePosted":"2026-09-10T00:00:00.000Z","validThrough":"2026-10-31T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"FORT YORK MEDICAL CLINIC"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"219 fort York Boulevard","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5V1B1","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a4ddcc0a641db6c310c562c"}}'::jsonb, '2026-10-04T05:13:35.032Z'
)
