INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '69e707736ce9c00c44637cca', 'https://physiciancareers.ca/jobs/100-virtual-endocrinology-focused-in-obesity-medicine-69e707736ce9c00c44637cca', '100% Virtual - Endocrinology focused in Obesity Medicine', 'Internal Medicine', 'full-time', 'Metabolite Clinic', 'downtown toronto', 'ON', '3219 Yonge Street', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, TRUE, FALSE, NULL, '2026-09-18', '2026-12-17', '2026-12-17', '2026-12-17', FALSE, '[]'::jsonb, '', 'About Us: Metabolite is a leading virtual metabolic clinic in Ontario, focused on improving access to high-quality, evidence-based care. We provide obesity care &amp; mens health focused in TRT through specialist-led treatment, dietitian support, and psychotherapy—all delivered online. Position Overview: We are seeking Internal Medicine / Endocrinologist with an interest in Obesity Medicine or Menopause focused on HRT to join our team. This position offers flexibility with part-time or full-time options, conducting patient consultations and follow-ups all virtually. Responsibilities: Develop and manage personalized obesity treatment plans, including prescribing anti-obesity medications when appropriate. Collaborate with a multidisciplinary team—including dietitian and psychotherapists—to provide holistic, evidence-based obesity care. Intergrating Healix our New AI Coaching for our patients covered part of their consultation. Qualifications: Licensed specialist in Ontario with CPSO. We welcome new grads! Proficiency with virtual care platforms and technology. Benefits: Fee for service billing, billings range from $2,000 - $4,000 Flexible work hours/days - Work as much or little including hours you control! Great way to supplement full time or part time work from home Direct OHIP billing integrated into our EMR system. Opportunity to work remotely from anywhere in Ontario.', '{"About":"Us: Metabolite is a leading virtual metabolic clinic in Ontario, focused on improving access to high-quality, evidence-based care. We provide obesity care &amp; mens health focused in TRT through specialist-led treatment, dietitian support, and psychotherapy—all delivered online. Position Overview: We are seeking Internal Medicine / Endocrinologist with an interest in Obesity Medicine or Menopause focused on HRT to join our team. This position offers flexibility with part-time or full-time options, conducting patient consultations and follow-ups all virtually.","Responsibilities":"Develop and manage personalized obesity treatment plans, including prescribing anti-obesity medications when appropriate. Collaborate with a multidisciplinary team—including dietitian and psychotherapists—to provide holistic, evidence-based obesity care. Intergrating Healix our New AI Coaching for our patients covered part of their consultation.","Qualifications":"Licensed specialist in Ontario with CPSO. We welcome new grads! Proficiency with virtual care platforms and technology. Benefits: Fee for service billing, billings range from $2,000 - $4,000 Flexible work hours/days - Work as much or little including hours you control! Great way to supplement full time or part time work from home Direct OHIP billing integrated into our EMR system. Opportunity to work remotely from anywhere in Ontario."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"100% Virtual - Endocrinology focused in Obesity Medicine","description":"About Us: Metabolite is a leading virtual metabolic clinic in Ontario, focused on improving access to high-quality, evidence-based care. We provide obesity care &amp; mens health focused in TRT through specialist-led treatment, dietitian support, and psychotherapy—all delivered online. Position Overview: We are seeking Internal Medicine / Endocrinologist with an interest in Obesity Medicine or Menopause focused on HRT to join our team. This position offers flexibility with part-time or full-time options, conducting patient consultations and follow-ups all virtually. Responsibilities: Develop and manage personalized obesity treatment plans, including prescribing anti-obesity medications when appropriate. Collaborate with a multidisciplinary team—including dietitian and psychotherapists—to provide holistic, evidence-based obesity care. Intergrating Healix our New AI Coaching for our patients covered part of their consultation. Qualifications: Licensed specialist in Ontario with CPSO. We welcome new grads! Proficiency with virtual care platforms and technology. Benefits: Fee for service billing, billings range from $2,000 - $4,000 Flexible work hours/days - Work as much or little including hours you control! Great way to supplement full time or part time work from home Direct OHIP billing integrated into our EMR system. Opportunity to work remotely from anywhere in Ontario.","datePosted":"2026-09-18T00:00:00.000Z","validThrough":"2026-12-17T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Metabolite Clinic"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"3219 Yonge Street","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M4N2L3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"69e707736ce9c00c44637cca"}}'::jsonb, '2026-10-04T05:13:44.801Z'
)
