INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aa8d3e45ffbbbfeb63fe82f', 'https://physiciancareers.ca/jobs/internist-with-cardiology-focus-6aa8d3e45ffbbbfeb63fe82f', 'Internist with Cardiology Focus', 'Internal Medicine', 'part-time', 'SP Cardio Clinics', 'downtown toronto', 'ON', '491 Lawrence Avenue West', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-09-14', '2026-12-13', '2026-12-13', '2026-12-13', FALSE, '["Kaizen@mdsearch.ca"]'::jsonb, '', 'Job type: Full-time, Part-time or Flexible MDSearch is recruiting Internists with a cardiology focus to join a dynamic and progressive team in Toronto, Ontario. This is an excellent opportunity for recent graduates or experienced professionals seeking dynamic environments. As a General Internist, your role will involve delivering comprehensive care to patients with cardiac and vascular conditions, while also performing diagnostic procedures. You will collaborate closely with a multidisciplinary team that includes Cardiologists, General Internists, and specialized cardiac care nurses to ensure the highest standard of patient care. This position offers the chance to work in a modern, well-equipped facility with a talented and experienced team. It presents a valuable opportunity to enhance your clinical expertise and contribute to advancements in cardiac and vascular care. Whether you’re looking for a full-time, part-time, or flexible schedule, this role provides a fulfilling career path in cardiology, enabling you to make a meaningful impact on patients&#39; health and well-being. ABOUT THE CLINIC The clinic offers a full range of diagnostic services, including nuclear testing, echocardiograms, cardiac sonography, stress tests, stress echo testing, Holter monitoring, and blood pressure monitoring. This professionally managed clinic is dedicated to delivering the highest quality patient care. A skilled team ensures all administrative and clinical operations are handled to an exceptional standard, allowing physicians to focus entirely on patient care. As part of an established and integral cardiology service in the region, the clinic offers a comprehensive range of diagnostic testing. You will join a team that understands each patient is unique and strives to develop personalized treatment plans for everyone. Requirements Independent Practice Certificate of Registration from the College of Physicians and Surgeons of Ontario (CPSO) Membership in good standing with the College of Physicians and Surgeons of Ontario (CPSO) Royal College certification in General Internal Medicine (or pending certification) US-trained specialists are exempt from The Royal College of Physicians and Surgeons eligibility requirements (US Board Certified Physicians are eligible for an independent license in Ontario) Internationally trained candidates who pass the subspecialty exam being launched by the CPSO (College of Physicians and Surgeons of Ontario) will be considered Medical liability insurance from the Canadian Medical Protective Association (CMPA) or equivalent required, appropriate to the category of practice Benefits 100% of your billing during the first month to support your ramp-up period Competitive overhead Set your own schedule, including evenings and weekends Control your patient volume to maximize income. Partnership opportunities available in future Dedicated administrative, medical records personnel, nuclear medicine and ECG technicians Flexible schedule, allowing you to manage patient volume at your comfort level, with established demand and patient flow. To apply: Send your CV to Kaizen@mdsearch.ca.', '{"About":"THE CLINIC The clinic offers a full range of diagnostic services, including nuclear testing, echocardiograms, cardiac sonography, stress tests, stress echo testing, Holter monitoring, and blood pressure monitoring. This professionally managed clinic is dedicated to delivering the highest quality patient care. A skilled team ensures all administrative and clinical operations are handled to an exceptional standard, allowing physicians to focus entirely on patient care. As part of an established and integral cardiology service in the region, the clinic offers a comprehensive range of diagnostic testing. You will join a team that understands each patient is unique and strives to develop personalized treatment plans for everyone. Requirements Independent Practice Certificate of Registration from the College of Physicians and Surgeons of Ontario (CPSO) Membership in good standing with the College of Physicians and Surgeons of Ontario (CPSO) Royal College certification in General Internal Medicine (or pending certification) US-trained specialists are exempt from The Royal College of Physicians and Surgeons eligibility requirements (US Board Certified Physicians are eligible for an independent license in Ontario) Internationally trained candidates who pass the subspecialty exam being launched by the CPSO (College of Physicians and Surgeons of Ontario) will be considered Medical liability insurance from the Canadian Medical Protective Association (CMPA) or equivalent required, appropriate to the category of practice Benefits 100% of your billing during the first month to support your ramp-up period Competitive overhead Set your own schedule, including evenings and weekends Control your patient volume to maximize income. Partnership opportunities available in future Dedicated administrative, medical records personnel, nuclear medicine and ECG technicians Flexible schedule, allowing you to manage patient volume at your comfort level, with established demand and patient flow. To apply: Send your CV to Kaizen@mdsearch.ca."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Internist with Cardiology Focus","description":"Job type: Full-time, Part-time or Flexible MDSearch is recruiting Internists with a cardiology focus to join a dynamic and progressive team in Toronto, Ontario. This is an excellent opportunity for recent graduates or experienced professionals seeking dynamic environments. As a General Internist, your role will involve delivering comprehensive care to patients with cardiac and vascular conditions, while also performing diagnostic procedures. You will collaborate closely with a multidisciplinary team that includes Cardiologists, General Internists, and specialized cardiac care nurses to ensure the highest standard of patient care. This position offers the chance to work in a modern, well-equipped facility with a talented and experienced team. It presents a valuable opportunity to enhance your clinical expertise and contribute to advancements in cardiac and vascular care. Whether you’re looking for a full-time, part-time, or flexible schedule, this role provides a fulfilling career path in cardiology, enabling you to make a meaningful impact on patients&#39; health and well-being. ABOUT THE CLINIC The clinic offers a full range of diagnostic services, including nuclear testing, echocardiograms, cardiac sonography, stress tests, stress echo testing, Holter monitoring, and blood pressure monitoring. This professionally managed clinic is dedicated to delivering the highest quality patient care. A skilled team ensures all administrative and clinical operations are handled to an exceptional standard, allowing physicians to focus entirely on patient care. As part of an established and integral cardiology service in the region, the clinic offers a comprehensive range of diagnostic testing. You will join a team that understands each patient is unique and strives to develop personalized treatment plans for everyone. Requirements Independent Practice Certificate of Registration from the College of Physicians and Surgeons of Ontario (CPSO) Membership in good standing with the College of Physicians and Surgeons of Ontario (CPSO) Royal College certification in General Internal Medicine (or pending certification) US-trained specialists are exempt from The Royal College of Physicians and Surgeons eligibility requirements (US Board Certified Physicians are eligible for an independent license in Ontario) Internationally trained candidates who pass the subspecialty exam being launched by the CPSO (College of Physicians and Surgeons of Ontario) will be considered Medical liability insurance from the Canadian Medical Protective Association (CMPA) or equivalent required, appropriate to the category of practice Benefits 100% of your billing during the first month to support your ramp-up period Competitive overhead Set your own schedule, including evenings and weekends Control your patient volume to maximize income. Partnership opportunities available in future Dedicated administrative, medical records personnel, nuclear medicine and ECG technicians Flexible schedule, allowing you to manage patient volume at your comfort level, with established demand and patient flow. To apply: Send your CV to Kaizen@mdsearch.ca.","datePosted":"2026-09-14T00:00:00.000Z","validThrough":"2026-12-13T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"SP Cardio Clinics"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"491 Lawrence Avenue West","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5M1C7","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa8d3e45ffbbbfeb63fe82f"}}'::jsonb, '2026-10-04T05:13:45.993Z'
