INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a9a54325ffbbbfeb6231b70', 'https://physiciancareers.ca/jobs/endocrinologist-or-general-internist-obesity-medicine-6a9a54325ffbbbfeb6231b70', 'Endocrinologist or General Internist – Obesity Medicine', 'Internal Medicine', 'full-time', 'Unify Health', 'downtown toronto', 'ON', '25 Industrial Street', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'hourly', 300, 300, 300, 600000, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-09-03', '2026-12-02', '2026-12-02', '2026-12-02', FALSE, '["Ginsberg@unifyhealth.ca"]'::jsonb, '', 'Unify Health is looking for an Endocrinologist or General Internist with specialization, training, or meaningful experience in Obesity Medicine to join our growing multidisciplinary team. We have a rapidly growing waitlist of patients seeking evidence-based management of obesity, metabolic syndrome, and related cardiometabolic disease. You would work alongside specialists in Cardiology, General Internal Medicine, Endocrinology, and other disciplines to provide comprehensive, medically appropriate care. This is not a “GLP-1 dispensary.” Our focus is proper longitudinal medicine: assessment of contributing factors and comorbidities, individualized treatment plans, medication management when appropriate, monitoring, and coordinated multidisciplinary care. The role is highly flexible. Care can be provided in person, virtually, or through a combination of both, at the physician’s discretion. Hours are flexible, with strong administrative and clinical support. What we offer: • Established and growing referral base • Flexible scheduling • In-person and virtual practice options • Competitive physician split • Potential earnings of &gt;$300/hour from home, with higher earning potential depending on practice style and volume • Accuro EMR • AI scribe support • Multidisciplinary specialist environment • Physician-owned and physician-led clinic We are especially interested in physicians who are passionate about high-quality obesity and metabolic medicine and want to help build a meaningful program rather than simply prescribe medications. Please reach out to Unify Health cofounder Dr Darrell Ginsberg at Ginsberg@unifyhealth.ca if interested in discussing the opportunity.', '{"About":"high-quality obesity and metabolic medicine and want to help build a meaningful program rather than simply prescribe medications. Please reach out to Unify Health cofounder Dr Darrell Ginsberg at Ginsberg@unifyhealth.ca if interested in discussing the opportunity."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Endocrinologist or General Internist – Obesity Medicine","description":"Unify Health is looking for an Endocrinologist or General Internist with specialization, training, or meaningful experience in Obesity Medicine to join our growing multidisciplinary team. We have a rapidly growing waitlist of patients seeking evidence-based management of obesity, metabolic syndrome, and related cardiometabolic disease. You would work alongside specialists in Cardiology, General Internal Medicine, Endocrinology, and other disciplines to provide comprehensive, medically appropriate care. This is not a “GLP-1 dispensary.” Our focus is proper longitudinal medicine: assessment of contributing factors and comorbidities, individualized treatment plans, medication management when appropriate, monitoring, and coordinated multidisciplinary care. The role is highly flexible. Care can be provided in person, virtually, or through a combination of both, at the physician’s discretion. Hours are flexible, with strong administrative and clinical support. What we offer: • Established and growing referral base • Flexible scheduling • In-person and virtual practice options • Competitive physician split • Potential earnings of &gt;$300/hour from home, with higher earning potential depending on practice style and volume • Accuro EMR • AI scribe support • Multidisciplinary specialist environment • Physician-owned and physician-led clinic We are especially interested in physicians who are passionate about high-quality obesity and metabolic medicine and want to help build a meaningful program rather than simply prescribe medications. Please reach out to Unify Health cofounder Dr Darrell Ginsberg at Ginsberg@unifyhealth.ca if interested in discussing the opportunity.","datePosted":"2026-09-03T00:00:00.000Z","validThrough":"2026-12-02T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Unify Health"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"25 Industrial Street","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M4G1Z2","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a9a54325ffbbbfeb6231b70"}}'::jsonb, '2026-10-04T05:13:49.289Z'
)
