INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a780b4dbfdb235d5f592915', 'https://physiciancareers.ca/jobs/physician-cancer-related-fatigue-clinic-6a780b4dbfdb235d5f592915', 'Physician, Cancer-Related Fatigue Clinic', 'Internal Medicine', 'part-time', 'Cancer Fatigue Services', 'north york', 'ON', '2 Sheppard Avenue East', 'Old Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-08-08', '2026-11-06', '2026-11-06', '2026-11-06', FALSE, '[]'::jsonb, '', 'Why This Clinic Exists Fatigue is the most commonly reported symptom in cancer and the one most likely to go untreated. Patients raise it, are told it is normal, and leave with nothing. We built Cancer Fatigue Services because that gap should not exist. CFS is Canada’s first physician-led, multidisciplinary practice dedicated entirely to cancer-related fatigue. Comprehensive medical assessment, cardiopulmonary exercise testing, supervised rehabilitation, and structured physician-led counselling, delivered as one coordinated longitudinal pathway. Why We Are Speaking to You Cancer-related fatigue is a differential diagnosis problem, and that is your discipline. Anemia. Thyroid dysfunction. Hypogonadism. Adrenal insufficiency. Sleep-disordered breathing. Treatment-related cardiotoxicity. Medication burden. Deconditioning. Mood. Any of them can produce profound exhaustion in a survivor, several are usually operating at once, and someone has to work through the list. Almost nobody does, which is why these patients arrive years after treatment ended having been told their bloodwork is fine. The physiology is measured, not estimated. Cardiopulmonary exercise testing at baseline and reassessment gives you integrated cardiac, pulmonary, and metabolic data on a symptom assessed almost everywhere else by questionnaire. Late treatment effects are an expanding clinical problem. Cardiovascular, pulmonary, endocrine sequelae, and metabolic consequences of long-term therapy are all growing as survival improves. There is room to build genuine expertise here. It is ambulatory and scheduled. No ward service, no consult pager, no call, no weekends. The Role Conduct comprehensive fatigue assessments covering presentation, oncologic and treatment history, symptom characterization, and functional status. Lead results delivery encounters and build the shared care plan with the patient and the team. Deliver the structured counselling encounters that anchor the care model. Session materials, scripts, workbooks, and documentation templates are built and in active use. Provide medical oversight to the rehabilitation and psychosocial teams. Coordinate ongoing care with referring oncologists, primary care providers, and other specialists. We Do Healthcare Differently We treat patients better by carrying the burden of navigating the system instead of handing it back to them. We treat clinicians the same way. High volumes with no downtime are how care quality erodes and how good physicians burn out, so we have built the clinic around concrete commitments: Administrative support, human and technological, so your attention stays on the patient. Fifteen to sixty minutes of team support attached to every encounter. Administrative time scheduled into your day, not appended to it. A buffer between encounters, set to your preference. You set your own schedule. We ask only for consistency week to week. No call, no after-hours coverage, no inpatient responsibility. Leave your work at work. We have built the clinic so that is actually possible. Terms Compensation: You keep 65% on comprehensive assessments and 70% on every other encounter type. Commitment: Our physicians work anywhere from three full days to two half-days per week. No minimum. Delivery: First OHIP-covered encounter on-site, most follow-ups virtual. Qualifications MD or equivalent, active and unrestricted CPSO licence, CMPA coverage, OHIP billing number. Demonstrated diagnostic skill with complex, multi-system presentations. Strong communication skills, particularly in conversations about function, loss, and expectation setting. Comfort in a multidisciplinary team and with structured, templated documentation. Assets: FRCPC in Internal Medicine, or a subspecialty background in cardiology, respirology, endocrinology, geriatrics, or physical medicine and rehabilitation. Experience interpreting cardiopulmonary exercise testing. Interest in clinical research.', '{"About":"function, loss, and expectation setting. Comfort in a multidisciplinary team and with structured, templated documentation. Assets: FRCPC in Internal Medicine, or a subspecialty background in cardiology, respirology, endocrinology, geriatrics, or physical medicine and rehabilitation. Experience interpreting cardiopulmonary exercise testing. Interest in clinical research.","Qualifications":"MD or equivalent, active and unrestricted CPSO licence, CMPA coverage, OHIP billing number. Demonstrated diagnostic skill with complex, multi-system presentations. Strong communication skills, particularly in conversations"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Physician, Cancer-Related Fatigue Clinic","description":"Why This Clinic Exists Fatigue is the most commonly reported symptom in cancer and the one most likely to go untreated. Patients raise it, are told it is normal, and leave with nothing. We built Cancer Fatigue Services because that gap should not exist. CFS is Canada’s first physician-led, multidisciplinary practice dedicated entirely to cancer-related fatigue. Comprehensive medical assessment, cardiopulmonary exercise testing, supervised rehabilitation, and structured physician-led counselling, delivered as one coordinated longitudinal pathway. Why We Are Speaking to You Cancer-related fatigue is a differential diagnosis problem, and that is your discipline. Anemia. Thyroid dysfunction. Hypogonadism. Adrenal insufficiency. Sleep-disordered breathing. Treatment-related cardiotoxicity. Medication burden. Deconditioning. Mood. Any of them can produce profound exhaustion in a survivor, several are usually operating at once, and someone has to work through the list. Almost nobody does, which is why these patients arrive years after treatment ended having been told their bloodwork is fine. The physiology is measured, not estimated. Cardiopulmonary exercise testing at baseline and reassessment gives you integrated cardiac, pulmonary, and metabolic data on a symptom assessed almost everywhere else by questionnaire. Late treatment effects are an expanding clinical problem. Cardiovascular, pulmonary, endocrine sequelae, and metabolic consequences of long-term therapy are all growing as survival improves. There is room to build genuine expertise here. It is ambulatory and scheduled. No ward service, no consult pager, no call, no weekends. The Role Conduct comprehensive fatigue assessments covering presentation, oncologic and treatment history, symptom characterization, and functional status. Lead results delivery encounters and build the shared care plan with the patient and the team. Deliver the structured counselling encounters that anchor the care model. Session materials, scripts, workbooks, and documentation templates are built and in active use. Provide medical oversight to the rehabilitation and psychosocial teams. Coordinate ongoing care with referring oncologists, primary care providers, and other specialists. We Do Healthcare Differently We treat patients better by carrying the burden of navigating the system instead of handing it back to them. We treat clinicians the same way. High volumes with no downtime are how care quality erodes and how good physicians burn out, so we have built the clinic around concrete commitments: Administrative support, human and technological, so your attention stays on the patient. Fifteen to sixty minutes of team support attached to every encounter. Administrative time scheduled into your day, not appended to it. A buffer between encounters, set to your preference. You set your own schedule. We ask only for consistency week to week. No call, no after-hours coverage, no inpatient responsibility. Leave your work at work. We have built the clinic so that is actually possible. Terms Compensation: You keep 65% on comprehensive assessments and 70% on every other encounter type. Commitment: Our physicians work anywhere from three full days to two half-days per week. No minimum. Delivery: First OHIP-covered encounter on-site, most follow-ups virtual. Qualifications MD or equivalent, active and unrestricted CPSO licence, CMPA coverage, OHIP billing number. Demonstrated diagnostic skill with complex, multi-system presentations. Strong communication skills, particularly in conversations about function, loss, and expectation setting. Comfort in a multidisciplinary team and with structured, templated documentation. Assets: FRCPC in Internal Medicine, or a subspecialty background in cardiology, respirology, endocrinology, geriatrics, or physical medicine and rehabilitation. Experience interpreting cardiopulmonary exercise testing. Interest in clinical research.","datePosted":"2026-08-08T00:00:00.000Z","validThrough":"2026-11-06T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Cancer Fatigue Services"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"2 Sheppard Avenue East","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M2N 6K9","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a780b4dbfdb235d5f592915"}}'::jsonb, '2026-10-04T05:13:52.931Z'
)
