) VALUES (
  '6a698b85df36206c30b27144', 'https://physiciancareers.ca/jobs/cardiology-6a698b85df36206c30b27144', 'Cardiology', 'Internal Medicine', 'full-time', 'Ontario Heart Center', 'etobicoke', 'ON', '100 Humber College Blvd', 'Toronto, ON', 43.6205, -79.5132, 11.08, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-07-28', '2026-10-23', '2026-10-23', '2026-10-23', FALSE, '[]'::jsonb, '', 'Physician Opportunities Ontario Heart Center is seeking an Internal Medicine Specialist with an interest in preventive and general cardiology to join its physician group in the Greater Toronto Area (GTA) . Full-time and part-time opportunities available. Compensation options: Fee-for-Service . Applications are welcome from both Canadian physicians and practicing physicians from the USA. Ontario Heart Center provides a network of experienced cardiologists and delivers comprehensive clinical and cardiac diagnostic services across Ontario.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Cardiology","description":"Physician Opportunities Ontario Heart Center is seeking an Internal Medicine Specialist with an interest in preventive and general cardiology to join its physician group in the Greater Toronto Area (GTA) . Full-time and part-time opportunities available. Compensation options: Fee-for-Service . Applications are welcome from both Canadian physicians and practicing physicians from the USA. Ontario Heart Center provides a network of experienced cardiologists and delivers comprehensive clinical and cardiac diagnostic services across Ontario.","datePosted":"2026-07-28T00:00:00.000Z","validThrough":"2026-10-23T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Ontario Heart Center"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"100 Humber College Blvd","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M9V5G4","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a698b85df36206c30b27144"}}'::jsonb, '2026-10-04T05:13:55.503Z'
)
