INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a6050c7df36206c30a38e2c', 'https://physiciancareers.ca/jobs/cardiologist-nuclear-cardiology-focus-qa-lab-advisor-6a6050c7df36206c30a38e2c', 'Cardiologist – Nuclear Cardiology Focus & QA Lab Advisor', 'Internal Medicine', 'part-time', 'SP Cardio Clinics', 'midtown', 'ON', '491 Lawrence Avenue West', 'Toronto, ON', 43.7001, -79.397, 5.33, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-07-21', '2026-10-19', '2026-10-19', '2026-10-19', FALSE, '[]'::jsonb, '', 'MDSearch is recruiting a non-invasive Cardiologist with a Nuclear Cardiology focus for an established community-based ambulatory cardiology clinic and diagnostic facility in midtown Toronto. The position is available on a full-time or part-time basis with flexible scheduling, making it an excellent opportunity for physicians seeking a rewarding clinical practice with genuine work-life balance. The clinic is staffed by a group of university- and hospital-affiliated Cardiologists and Respirologists, and these institutional affiliations allow seamless continuity with upstream hospital-based cardiac services. The Role Provide comprehensive outpatient cardiology consultation and follow-up services Serve as Quality Assurance (QA) Advisor for an accredited Nuclear Cardiology Laboratory Oversee quality assurance activities within the lab&#39;s quality management program Participate in protocol development and review, and monitor quality metrics Ensure ongoing compliance with accreditation standards Collaborate with Nuclear Medicine Technologists to promote excellence in patient care About the Clinic This professionally managed clinic is dedicated to delivering the highest quality patient care. A dedicated administrative team handles all clinical and administrative operations, allowing physicians to focus on what matters most — patient care. Qualifications Certification in Cardiology by the Royal College of Physicians and Surgeons of Canada, or equivalent acceptable for CPSO registration Eligibility for independent or provisional licensure with the College of Physicians and Surgeons of Ontario (CPSO) Fellowship training and demonstrated expertise in Nuclear Cardiology (CBNC certification or Royal College certification in Nuclear Medicine) Experience with Nuclear Cardiology laboratory quality assurance programs preferred Full-time commitment preferred This position combines a high-quality outpatient clinical practice with a leadership role in maintaining the quality and safety of a modern Nuclear Cardiology laboratory. Start date: as soon as possible.', '{"About":"the Clinic This professionally managed clinic is dedicated to delivering the highest quality patient care. A dedicated administrative team handles all clinical and administrative operations, allowing physicians to focus on what matters most — patient care.","Qualifications":"Certification in Cardiology by the Royal College of Physicians and Surgeons of Canada, or equivalent acceptable for CPSO registration Eligibility for independent or provisional licensure with the College of Physicians and Surgeons of Ontario (CPSO) Fellowship training and demonstrated expertise in Nuclear Cardiology (CBNC certification or Royal College certification in Nuclear Medicine) Experience with Nuclear Cardiology laboratory quality assurance programs preferred Full-time commitment preferred This position combines a high-quality outpatient clinical practice with a leadership role in maintaining the quality and safety of a modern Nuclear Cardiology laboratory. Start date: as soon as possible."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Cardiologist – Nuclear Cardiology Focus & QA Lab Advisor","description":"MDSearch is recruiting a non-invasive Cardiologist with a Nuclear Cardiology focus for an established community-based ambulatory cardiology clinic and diagnostic facility in midtown Toronto. The position is available on a full-time or part-time basis with flexible scheduling, making it an excellent opportunity for physicians seeking a rewarding clinical practice with genuine work-life balance. The clinic is staffed by a group of university- and hospital-affiliated Cardiologists and Respirologists, and these institutional affiliations allow seamless continuity with upstream hospital-based cardiac services. The Role Provide comprehensive outpatient cardiology consultation and follow-up services Serve as Quality Assurance (QA) Advisor for an accredited Nuclear Cardiology Laboratory Oversee quality assurance activities within the lab&#39;s quality management program Participate in protocol development and review, and monitor quality metrics Ensure ongoing compliance with accreditation standards Collaborate with Nuclear Medicine Technologists to promote excellence in patient care About the Clinic This professionally managed clinic is dedicated to delivering the highest quality patient care. A dedicated administrative team handles all clinical and administrative operations, allowing physicians to focus on what matters most — patient care. Qualifications Certification in Cardiology by the Royal College of Physicians and Surgeons of Canada, or equivalent acceptable for CPSO registration Eligibility for independent or provisional licensure with the College of Physicians and Surgeons of Ontario (CPSO) Fellowship training and demonstrated expertise in Nuclear Cardiology (CBNC certification or Royal College certification in Nuclear Medicine) Experience with Nuclear Cardiology laboratory quality assurance programs preferred Full-time commitment preferred This position combines a high-quality outpatient clinical practice with a leadership role in maintaining the quality and safety of a modern Nuclear Cardiology laboratory. Start date: as soon as possible.","datePosted":"2026-07-21T00:00:00.000Z","validThrough":"2026-10-19T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"SP Cardio Clinics"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"491 Lawrence Avenue West","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5M1C7","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a6050c7df36206c30a38e2c"}}'::jsonb, '2026-10-04T05:13:57.410Z'
)
