  '6a5b12d2df36206c309a8cb9', 'https://physiciancareers.ca/jobs/respirologist-midtown-toronto-6a5b12d2df36206c309a8cb9', 'Respirologist Midtown Toronto', 'Internal Medicine', 'full-time', 'The Lung Clinic', 'midtown', 'ON', '1849 Yonge Street', 'Toronto, ON', 43.7001, -79.397, 5.33, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-07-17', '2026-10-15', '2026-10-15', '2026-10-15', FALSE, '[]'::jsonb, '', 'Part time or Full time Respirologist required for a busy respiratory practice. There is a Level 3 PFT Lab and radiology clinic on site. Respirologist bills professional fees for the PFTs. Fees split is negotiable. Additional work at the busy sister Sleep Center is also available.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Respirologist Midtown Toronto","description":"Part time or Full time Respirologist required for a busy respiratory practice. There is a Level 3 PFT Lab and radiology clinic on site. Respirologist bills professional fees for the PFTs. Fees split is negotiable. Additional work at the busy sister Sleep Center is also available.","datePosted":"2026-07-17T00:00:00.000Z","validThrough":"2026-10-15T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"The Lung Clinic"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1849 Yonge Street","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M4S1Y2","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a5b12d2df36206c309a8cb9"}}'::jsonb, '2026-10-04T05:13:58.961Z'
)
