  '6a5b12d1df36206c309a8c8d', 'https://physiciancareers.ca/jobs/sleep-medicine-6a5b12d1df36206c309a8c8d', 'Sleep Medicine', 'Internal Medicine', 'full-time', 'Centre for Sleep', 'richmond hill', 'ON', '295 College Street', 'Toronto, ON', 43.8828, -79.4403, 25.94, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-07-17', '2026-10-15', '2026-10-15', '2026-10-15', FALSE, '[]'::jsonb, '', 'Well reputed Sleep Centre with balanced focus on sleep apnea and other sleep disorders. Busy location. Presently staffed for 9 sleep beds 7 nights a week. Additional sleep work is also available at the sister facilities in North York, Vaughan, Richmond Hill and Cobourg. Fees split is negotiable. Opportunity to participate in CBTI group sessions currently underway at the centre. The candidate may also develop full psychiatry practice in addition to the sleep practice at this location which is located next to CAMH.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Sleep Medicine","description":"Well reputed Sleep Centre with balanced focus on sleep apnea and other sleep disorders. Busy location. Presently staffed for 9 sleep beds 7 nights a week. Additional sleep work is also available at the sister facilities in North York, Vaughan, Richmond Hill and Cobourg. Fees split is negotiable. Opportunity to participate in CBTI group sessions currently underway at the centre. The candidate may also develop full psychiatry practice in addition to the sleep practice at this location which is located next to CAMH.","datePosted":"2026-07-17T00:00:00.000Z","validThrough":"2026-10-15T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Centre for Sleep"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"295 College Street","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5T1S2","addressCountr