INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a5eff6cdf36206c30a14f96', 'https://physiciancareers.ca/jobs/academic-neuromuscular-neurologist-6a5eff6cdf36206c30a14f96', 'Academic Neuromuscular Neurologist', 'Neurology', 'full-time', 'University Health Network', 'downtown toronto', 'ON', '200 Elizabeth Street', 'Old Toronto, ON', 43.6532, -79.3832, 0, NULL, 'annual', 290000, 295000, 292500, 292500, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-07-20', '2026-10-18', '2026-10-18', '2026-10-18', FALSE, '["hans.katzberg@uhn.ca","uoft.careers@utoronto.ca"]'::jsonb, '', 'The Division of Neurology, Department of Medicine, University Health Network/Sinai Health System (UHN/SHS) at the University of Toronto is seeking a full-time, permanent Academic Neurologist with a focus on movement disorders. The candidate must be eligible for a full-time clinical academic appointment at the rank of Assistant Professor or higher with a preference of the position description of Clinician Investigator at the University of Toronto. For Clinician Investigator, scholarly excellence will be assessed by the presence of research grants, publications in leading journals, invited presentations at significant conferences, awards, accolades, and other related accomplishments. The effective start date is at a mutually agreed upon date after January 2027. The successful candidate will hold a MD degree and should have, or be eligible for, certification in Neurology by the Royal College of Physicians and Surgeons of Canada and licensure with the College of Physicians and Surgeons of Ontario (CPSO). TO be considered for a Clinician Investigator position, specific additional training such as a Master’s degree or equivalent is required. Academic appointment will be within the Division of Neurology, Department of Medicine, University of Toronto. Salary range will be in the range of $290,000-295,000 CAD per year dependent on clinical work. Research and clinical focus will be on movement disorders. Clinical service will be in the Division of Neurology, KBI for on-call, inpatient and ambulatory care. Teaching will be as per Division of Neurology requirements.Salary will be commensurate with training and experience. For more information about the Department of Medicine, University of Toronto; diversity and accessibility statements see https://www.deptmedicine.utoronto.ca . All qualified candidates are encouraged to apply; however, Canadians and permanent residents will be given priority. Applications will be accepted until September 30th 2026 . Please send your curriculum vitae, three references letters and a letter of application to: Dr. Hans Katzberg, Division of Neurology, Toronto General Hospital 200 Elizabeth Street, Toronto ON, Canada M5G 2C4. Email: hans.katzberg@uhn.ca Diversity Statement The University of Toronto is strongly committed to diversity within its community and especially welcomes applications from racialized persons/persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ2S+ persons, and others who may contribute to the further diversification of ideas. Accessibility Statement The University strives to be an equitable and inclusive community, and proactively seeks to increase diversity among its community members. Our values regarding equity and diversity are linked with our unwavering commitment to excellence in the pursuit of our academic mission. The University is committed to the principles of the Accessibility for Ontarians with Disabilities Act (AODA). As such, we strive to make our recruitment, assessment and selection processes as accessible as possible and prove accommodations as required for applicants with disabilities. If you require any accommodations at any point during the application and hiring process, please contact uoft.careers@utoronto.ca The University of Toronto is strongly committed to diversity within its community and especially welcomes applications from racialized persons / persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ2S+ persons, and others who may contribute to the further diversification of ideas.', '{"About":"the Department of Medicine, University of Toronto; diversity and accessibility statements see https://www.deptmedicine.utoronto.ca . All qualified candidates are encouraged to apply; however, Canadians and permanent residents will be given priority. Applications will be accepted until September 30th 2026 . Please send your curriculum vitae, three references letters and a letter of application to: Dr. Hans Katzberg, Division of Neurology, Toronto General Hospital 200 Elizabeth Street, Toronto ON, Canada M5G 2C4. Email: hans.katzberg@uhn.ca Diversity Statement The University of Toronto is strongly committed to diversity within its community and especially welcomes applications from racialized persons/persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ2S+ persons, and others who may contribute to the further diversification of ideas. Accessibility Statement The University strives to be an equitable and inclusive community, and proactively seeks to increase diversity among its community members. Our values regarding equity and diversity are linked with our unwavering commitment to excellence in the pursuit of our academic mission. The University is committed to the principles of the Accessibility for Ontarians with Disabilities Act (AODA). As such, we strive to make our recruitment, assessment and selection processes as accessible as possible and prove accommodations as required for applicants with disabilities. If you require any accommodations at any point during the application and hiring process, please contact uoft.careers@utoronto.ca The University of Toronto is strongly committed to diversity within its community and especially welcomes applications from racialized persons / persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ2S+ persons, and others who may contribute to the further diversification of ideas."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Academic Neuromuscular Neurologist","description":"The Division of Neurology, Department of Medicine, University Health Network/Sinai Health System (UHN/SHS) at the University of Toronto is seeking a full-time, permanent Academic Neurologist with a focus on movement disorders. The candidate must be eligible for a full-time clinical academic appointment at the rank of Assistant Professor or higher with a preference of the position description of Clinician Investigator at the University of Toronto. For Clinician Investigator, scholarly excellence will be assessed by the presence of research grants, publications in leading journals, invited presentations at significant conferences, awards, accolades, and other related accomplishments. The effective start date is at a mutually agreed upon date after January 2027. The successful candidate will hold a MD degree and should have, or be eligible for, certification in Neurology by the Royal College of Physicians and Surgeons of Canada and licensure with the College of Physicians and Surgeons of Ontario (CPSO). TO be considered for a Clinician Investigator position, specific additional training such as a Master’s degree or equivalent is required. Academic appointment will be within the Division of Neurology, Department of Medicine, University of Toronto. Salary range will be in the range of $290,000-295,000 CAD per year dependent on clinical work. Research and clinical focus will be on movement disorders. Clinical service will be in the Division of Neurology, KBI for on-call, inpatient and ambulatory care. Teaching will be as per Division of Neurology requirements.Salary will be commensurate with training and experience. For more information about the Department of Medicine, University of Toronto; diversity and accessibility statements see https://www.deptmedicine.utoronto.ca . All qualified candidates are encouraged to apply; however, Canadians and permanent residents will be given priority. Applications will be accepted until September 30th 2026 . Please send your curriculum vitae, three references letters and a letter of application to: Dr. Hans Katzberg, Division of Neurology, Toronto General Hospital 200 Elizabeth Street, Toronto ON, Canada M5G 2C4. Email: hans.katzberg@uhn.ca Diversity Statement The University of Toronto is strongly committed to diversity within its community and especially welcomes applications from racialized persons/persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ2S+ persons, and others who may contribute to the further diversification of ideas. Accessibility Statement The University strives to be an equitable and inclusive community, and proactively seeks to increase diversity among its community members. Our values regarding equity and diversity are linked with our unwavering commitment to excellence in the pursuit of our academic mission. The University is committed to the principles of the Accessibility for Ontarians with Disabilities Act (AODA). As such, we strive to make our recruitment, assessment and selection processes as accessible as possible and prove accommodations as required for applicants with disabilities. If you require any accommodations at any point during the application and hiring process, please contact uoft.careers@utoronto.ca The University of Toronto is strongly committed to diversity within its community and especially welcomes applications from racialized persons / persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ2S+ persons, and others who may contribute to the further diversification of ideas.","datePosted":"2026-07-20T00:00:00.000Z","validThrough":"2026-10-18T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"University Health Network"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"200 Elizabeth Street","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M5G 2A7","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a5eff6cdf36206c30a14f96"}}'::jsonb, '2026-10-04T05:14:13.734Z'
)
