  '6a586926df36206c309634b9', 'https://physiciancareers.ca/jobs/neurologist-6a586926df36206c309634b9', 'Neurologist', 'Neurology', 'part-time', 'Ontario Heart Center', 'etobicoke', 'ON', '100 Humber College Blvd', 'Toronto, ON', 43.6205, -79.5132, 11.08, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-07-15', '2026-10-12', '2026-10-12', '2026-10-12', FALSE, '[]'::jsonb, '', 'Ontario Heart Center is seeking a Neurologist to join its physician group in the GTA. Part-time opportunity is available; contact us for additional details. The Ontario Heart Center has a network of experienced cardiologists, internists, and nephrologists, and it provides comprehensive clinical and diagnostic services across Ontario.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Neurologist","description":"Ontario Heart Center is seeking a Neurologist to join its physician group in the GTA. Part-time opportunity is available; contact us for additional details. The Ontario Heart Center has a network of experienced cardiologists, internists, and nephrologists, and it provides comprehensive clinical and diagnostic services across Ontario.","datePosted":"2026-07-15T00:00:00.000Z","validThrough":"2026-10-12T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Ontario Heart Center"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"100 Humber College Blvd","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M9V5G4","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a586926df36206c309634b9"}}'::jsonb, '2026-10-04T05:14:14.707Z'
