INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a00129f76abc2c85cb8656f', 'https://physiciancareers.ca/jobs/after-hours-crew-urgent-care-pediatricians-welcome-6a00129f76abc2c85cb8656f', 'AFTER HOURS CREW - URGENT CARE PEDIATRICIANS WELCOME!', 'Pediatrics', 'full-time', 'Kidcrew', 'north york', 'ON', '1440 Bathurst St', 'Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-09-19', '2026-12-18', '2026-12-18', '2026-12-18', FALSE, '[]'::jsonb, '', 'Pediatricians , full-time or part-time, for our urgent care/after-hours clinics Brand new multi-disciplinary clinics in midtown Toronto and North York JOIN THE BIGGEST AND MOST RECOMMENDED PEDIATRIC CLINIC IN CANADA! DAYTIME OR AFTER-HOURS POSITIONS ARE AVAILABLE New, tech-enhanced offices. The EMR is PS Suite (Telus). Our professional office staff handles all the administrative tasks. ❤ Flexibility in hours : the ability to work part-time, FT, evenings or weekends ❤ You decide how many patients you want to see and how many hours you work. ❤ Large, multidisciplinary pediatric group. Easily refer to other pediatricians for follow-up, or specialists for consultation. ❤ Attractive fee split At Kidcrew, we have created a forward-thinking and innovative children’s clinic focusing on family-centred care and wellness for children of all ages. Kidcrew is a new Pediatric multi-disciplinary clinic in midtown Toronto. We are looking to bring on excellent, eager and friendly pediatricians and specialists. Several pediatricians provide well-baby care, sick visits and general pediatrics to our community of over 130,000 patients. We care for patients Ontario-wide, including a focus on underserviced and vulnerable communities. Nursing care is provided by the clinic. We are passionate about providing quality pediatric care for kids and families. Telus Practice Solutions EMR and technology focused on improving clinician communication and efficiency are used in the practice along with well-qualified, friendly, support staff. From our friendly front desk staff to our non-traditional 2,000 square-foot patient lounges, Kidcrew is committed to providing an exceptional patient experience. Our team consists of pediatricians and a variety of pediatric sub specialists. Alongside, dietitians, speech-language pathologists, physiotherapists, occupational therapists, chiropractors, psychologists and many other team members work together to provide a comprehensive and collaborative model under one roof. Join us on our journey in changing childrens&#39; healthcare for the better. Kidcrew.com', '{"About":"providing quality pediatric care for kids and families. Telus Practice Solutions EMR and technology focused on improving clinician communication and efficiency are used in the practice along with well-qualified, friendly, support staff. From our friendly front desk staff to our non-traditional 2,000 square-foot patient lounges, Kidcrew is committed to providing an exceptional patient experience. Our team consists of pediatricians and a variety of pediatric sub specialists. Alongside, dietitians, speech-language pathologists, physiotherapists, occupational therapists, chiropractors, psychologists and many other team members work together to provide a comprehensive and collaborative model under one roof. Join us on our journey in changing childrens&#39; healthcare for the better. Kidcrew.com"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"AFTER HOURS CREW - URGENT CARE PEDIATRICIANS WELCOME!","description":"Pediatricians , full-time or part-time, for our urgent care/after-hours clinics Brand new multi-disciplinary clinics in midtown Toronto and North York JOIN THE BIGGEST AND MOST RECOMMENDED PEDIATRIC CLINIC IN CANADA! DAYTIME OR AFTER-HOURS POSITIONS ARE AVAILABLE New, tech-enhanced offices. The EMR is PS Suite (Telus). Our professional office staff handles all the administrative tasks. ❤ Flexibility in hours : the ability to work part-time, FT, evenings or weekends ❤ You decide how many patients you want to see and how many hours you work. ❤ Large, multidisciplinary pediatric group. Easily refer to other pediatricians for follow-up, or specialists for consultation. ❤ Attractive fee split At Kidcrew, we have created a forward-thinking and innovative children’s clinic focusing on family-centred care and wellness for children of all ages. Kidcrew is a new Pediatric multi-disciplinary clinic in midtown Toronto. We are looking to bring on excellent, eager and friendly pediatricians and specialists. Several pediatricians provide well-baby care, sick visits and general pediatrics to our community of over 130,000 patients. We care for patients Ontario-wide, including a focus on underserviced and vulnerable communities. Nursing care is provided by the clinic. We are passionate about providing quality pediatric care for kids and families. Telus Practice Solutions EMR and technology focused on improving clinician communication and efficiency are used in the practice along with well-qualified, friendly, support staff. From our friendly front desk staff to our non-traditional 2,000 square-foot patient lounges, Kidcrew is committed to providing an exceptional patient experience. Our team consists of pediatricians and a variety of pediatric sub specialists. Alongside, dietitians, speech-language pathologists, physiotherapists, occupational therapists, chiropractors, psychologists and many other team members work together to provide a comprehensive and collaborative model under one roof. Join us on our journey in changing childrens&#39; healthcare for the better. Kidcrew.com","datePosted":"2026-09-19T00:00:00.000Z","validThrough":"2026-12-18T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Kidcrew"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1440 Bathurst St","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5R3J3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a00129f76abc2c85cb8656f"}}'::jsonb, '2026-10-04T05:15:05.979Z'
)
