INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6aa0ebf25ffbbbfeb62ea82e', 'https://physiciancareers.ca/jobs/academic-clinician-staff-physician-clinical-and-metabolic-genetics-6aa0ebf25ffbbbfeb62ea82e', 'Academic clinician staff Physician. Clinical and Metabolic Genetics', 'Pediatrics', 'full-time', 'The Hospital for Sick Children', 'downtown toronto', 'ON', '555 University Avenue', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'annual', 275543, 340000, 307772, 307772, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-09-08', '2026-12-07', '2026-12-07', '2026-12-07', FALSE, '["roberto.mendoza@sickkids.ca"]'::jsonb, '', 'Hospital for Sick Children, Division of Clinical and Metabolic Genetics Effective July 1, 2027, the Department of Paediatrics, Temerity Faculty of Medicine at the University of Toronto and the Division of Clinical and Metabolic Genetics at The Hospital for Sick Children, 555 University Avenue, Toronto, Ontario, an academic health science centre dedicated exclusively to children, affiliated with the University of Toronto, is recruiting a full-time permanent academic clinician staff physician. The Division of Clinical and Metabolic Genetics has a long tradition of excellence in clinical care, education, and innovative research. Independent and collaborative clinical and basic research is performed by Division members. The Division hosts a residency training programs in addition to fellowship programs in Clinical Biochemical Genetics and Laboratory Biochemical Genetics, which are fully accredited by the Royal College of Physicians and Surgeons of Canada and the Canadian College of Medical Geneticists (CCMG). The Hospital for Sick Children has a full service biochemical diagnostic laboratory hosted within the Department of Pathology and Laboratory Medicine. The successful candidate will join a dynamic interprofessional care team. The successful candidate will provide care for clinical genetics patients in the outpatient settings and inpatient consultation service. Specific interest and expertise in methylation disorders, overgrowth and mechanisms of imprinting is preferred but not required. Experience with interpretation of results of long-read genome wide sequencing, RNA sequencing and methylation tests would be highly desirable. Evidence of excellence in teaching and research is required. Candidates at all career stages are encouraged to apply. All candidates must be able to function proficiently in English, hold an MD, MBBS or equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable qualifications. Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. This position will remain open until filled. The successful candidate will be eligible for an academic appointment at the University of Toronto. Rank and salary ($275,543 to $340,000) per annum will be commensurate with qualifications and experience. The successful candidate will be eligible for a benefits package which includes medical, dental, life insurance, long term disability insurance, group insurance, pension plan, vision care, academic allowance, and a relocation package. Interested individuals should submit a letter of application, curriculum vitae, and the names and addresses of three referees to: Dr. Roberto Mendoza, Head, Division of Clinical and Metabolic Genetics, Department of Paediatrics, email: roberto.mendoza@sickkids.ca The Hospital for Sick Children, 555 University Avenue, Toronto, Ontario Canada M5G 1X8. The University of Toronto and The Hospital for Sick Children are strongly committed to diversity within its community. Both institutions recognize systemic barriers that impact equity seeking groups. As such, we welcome applications from historically marginalized groups including Black, Indigenous, and Racialized people, women, LGBTQIA+, and/or persons with disabilities. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities.', '{"Qualifications":". Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. This position will remain open until filled. The successful candidate will be eligible for an academic appointment at the University of Toronto. Rank and salary ($275,543 to $340,000) per annum will be commensurate with"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Academic clinician staff Physician. Clinical and Metabolic Genetics","description":"Hospital for Sick Children, Division of Clinical and Metabolic Genetics Effective July 1, 2027, the Department of Paediatrics, Temerity Faculty of Medicine at the University of Toronto and the Division of Clinical and Metabolic Genetics at The Hospital for Sick Children, 555 University Avenue, Toronto, Ontario, an academic health science centre dedicated exclusively to children, affiliated with the University of Toronto, is recruiting a full-time permanent academic clinician staff physician. The Division of Clinical and Metabolic Genetics has a long tradition of excellence in clinical care, education, and innovative research. Independent and collaborative clinical and basic research is performed by Division members. The Division hosts a residency training programs in addition to fellowship programs in Clinical Biochemical Genetics and Laboratory Biochemical Genetics, which are fully accredited by the Royal College of Physicians and Surgeons of Canada and the Canadian College of Medical Geneticists (CCMG). The Hospital for Sick Children has a full service biochemical diagnostic laboratory hosted within the Department of Pathology and Laboratory Medicine. The successful candidate will join a dynamic interprofessional care team. The successful candidate will provide care for clinical genetics patients in the outpatient settings and inpatient consultation service. Specific interest and expertise in methylation disorders, overgrowth and mechanisms of imprinting is preferred but not required. Experience with interpretation of results of long-read genome wide sequencing, RNA sequencing and methylation tests would be highly desirable. Evidence of excellence in teaching and research is required. Candidates at all career stages are encouraged to apply. All candidates must be able to function proficiently in English, hold an MD, MBBS or equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable qualifications. Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. This position will remain open until filled. The successful candidate will be eligible for an academic appointment at the University of Toronto. Rank and salary ($275,543 to $340,000) per annum will be commensurate with qualifications and experience. The successful candidate will be eligible for a benefits package which includes medical, dental, life insurance, long term disability insurance, group insurance, pension plan, vision care, academic allowance, and a relocation package. Interested individuals should submit a letter of application, curriculum vitae, and the names and addresses of three referees to: Dr. Roberto Mendoza, Head, Division of Clinical and Metabolic Genetics, Department of Paediatrics, email: roberto.mendoza@sickkids.ca The Hospital for Sick Children, 555 University Avenue, Toronto, Ontario Canada M5G 1X8. The University of Toronto and The Hospital for Sick Children are strongly committed to diversity within its community. Both institutions recognize systemic barriers that impact equity seeking groups. As such, we welcome applications from historically marginalized groups including Black, Indigenous, and Racialized people, women, LGBTQIA+, and/or persons with disabilities. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities.","datePosted":"2026-09-08T00:00:00.000Z","validThrough":"2026-12-07T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"The Hospital for Sick Children"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"555 University Avenue","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5G1X8","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa0ebf25ffbbbfeb62ea82e"}}'::jsonb, '2026-10-04T05:15:07.982Z'
)
