  '6a868bebbfdb235d5f7079c8', 'https://physiciancareers.ca/jobs/ftpt-pediatrician-6a868bebbfdb235d5f7079c8', 'FT/PT Pediatrician', 'Pediatrics', 'full-time', '303Pediatrics', 'etobicoke', 'ON', '722-115 Humber College Blvd', 'Toronto, ON', 43.6205, -79.5132, 11.08, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, FALSE, FALSE, NULL, '2026-08-19', '2026-11-17', '2026-11-17', '2026-11-17', FALSE, '[]'::jsonb, '', 'Etobicoke, Toronto ON Paediatric Practice: Large well-established group seeking full-time/part-time pediatricians. EMR. Onsite lab, x-ray and pharmacy. Beside Etobicoke Hospital WOHC. New office - Etobicoke Wellness Centre. Website https://www.pediatricsathumbercollege.ca/', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"FT/PT Pediatrician","description":"Etobicoke, Toronto ON Paediatric Practice: Large well-established group seeking full-time/part-time pediatricians. EMR. Onsite lab, x-ray and pharmacy. Beside Etobicoke Hospital WOHC. New office - Etobicoke Wellness Centre. Website https://www.pediatricsathumbercollege.ca/","datePosted":"2026-08-19T00:00:00.000Z","validThrough":"2026-11-17T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"303Pediatrics"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"722-115 Humber College Blvd","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M9V0A9","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a868bebbfdb235d5f7079c8"}}'::jsonb, '2026-10-04T05:15:11.822Z'
