INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a83ea14bfdb235d5f6bee2c', 'https://physiciancareers.ca/jobs/dentist-in-chief-department-of-paediatric-dentistry-6a83ea14bfdb235d5f6bee2c', 'Dentist-in-Chief – Department of Paediatric Dentistry', 'Pediatrics', 'full-time', 'The Hospital for Sick Children', 'downtown toronto', 'ON', '555 University Avenue', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'annual', 200000, 400000, 300000, 300000, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-08-17', '2026-11-15', '2026-11-15', '2026-11-15', FALSE, '["dentistrydepartmentchief.recruitment@sickkids.ca","uoft.careers@utoronto.ca"]'::jsonb, '', 'The Department of Paediatric Dentistry at The Hospital for Sick Children (SickKids), Faculty of Dentistry, University of Toronto, is inviting applications for the position of Dentist-in-Chief. This is a full-time role for an academic paediatric dentist and leader in paediatric oral health. The effective date of this appointment is June 2027 but can be negotiated. Primary Description Responsibilities include full clinical practice, research, and education, and administrative responsibilities as required by a Department Chief. Evidence of excellence in teaching and research is required. This role reports directly to the Chief of Peri-Operative Services. Additional Description The successful candidate should be a senior academic with an international reputation who can provide effective and collaborative leadership and vision at the hospital, provincial, national and international levels. The candidate must be eligible for appointment at the rank of Associate Professor at the University of Toronto and be eligible for certification with the Royal College of Dental Surgeons of Ontario. Candidates must obtain an appropriate Visa, if applicable. We are seeking an individual whose leadership qualifications include management proficiency, dispute resolution, communications expertise, mentoring capabilities, the ability to engender trust, function collaboratively with all manner of clinical teams and administration. Additionally, the successful candidate will have a long-term vision for the Department which integrates with the mission of Peri-Operative Services, the Hospital and the University of Toronto. Salary will be in the range of $200,000 to $400,000 for 40 hours per week, commensurate with qualifications and experience, and which will be supplemented by clinical billing activity. Benefits include Medical, Dental, Life, Group Insurance, Pension, Vision. A per annum stipend, in recognition of the administrative leadership responsibilities associated with the Department Chief role, will be provided. Support for relocation expenses will be offered. The position has a potential duration of two terms of five years each. Department Description The Department of Paediatric Dentistry at The Hospital for Sick Children consist of 18 dental surgeons, orthodontists and paediatric dentists, provides dental care for children and adolescents under 18 years whose treatment is best managed in a multidisciplinary hospital environment. It is integral to the Ontario Cleft Lip and Palate Craniofacial Dental program and is a major clinical training and research centre for the University of Toronto Graduate Paediatric Dentistry program. The Department also provides training to hospital staff, community dentists, physicians and families through affiliation with the University of Toronto. Hospital Description SickKids, located at 555 University Avenue in downtown Toronto, is among the largest children’s hospitals in North America and has a long history of excellence in clinical care, research and education. It was named the number one paediatric hospital in the world in 2025, by Newsweek magazine. SickKids is fully affiliated with the University of Toronto and is located adjacent to the University campus and to numerous specialty hospitals and biomedical research institutes. Toronto is a vibrant and multicultural city, widely recognized as one of the most diverse cities in the world, with approximately half of its residents born outside Canada and representation from more than 250 ethnicities. This diversity is reflected in the city’s neighbourhoods, food scene, Michelin-starred restaurants across Toronto and the surrounding region, and strengths in key sectors such as life sciences, finance, information, and communications technology. As one of the largest cities in North America, Toronto offers a dynamic downtown, diverse neighbourhoods, strong schools, and access to leading universities. It is regularly recognized in global city, travel, and liveability rankings. World-famous lake and wilderness country and year-round outdoor recreation are easily accessible, as are two hub airports for regional and international travel. Application Process Applications will be accepted until October 30, 2026. Should you be interested in this opportunity, please forward a one-page statement of interest [which includes the names and contact information for 3 referees] and curriculum vitae, in PDF format, via email to: Dr. Abhaya V. Kulkarni Chief, Peri-Operative Services and Chair of the Search Committee 175 Elizabeth St, Toronto, ON M5G 2G3 EMAIL: dentistrydepartmentchief.recruitment@sickkids.ca All qualified candidates are encouraged to apply; however, Canadians and permanent residents will be given priority. For more information about the University of Toronto, Department of Paediatric Dentistry, please visit our home page at https://www.dentistry.utoronto.ca Diversity Statement The University of Toronto embraces Diversity and is building a culture of belonging that increases our capacity to effectively address and serve the interests of our global community. We strongly encourage applications from Indigenous Peoples, Black and racialized persons, women, persons with disabilities, and people of diverse sexual and gender identities. We value applicants who have demonstrated a commitment to equity, diversity and inclusion and recognize that diverse perspectives, experiences, and expertise are essential to strengthening our academic mission. Accessibility Statement The University strives to be an equitable and inclusive community and proactively seeks to increase diversity among its community members. Our values regarding equity and diversity are linked with our unwavering commitment to excellence in the pursuit of our academic mission. The University is committed to the principles of the Accessibility for Ontarians with Disabilities Act (AODA). As such, we strive to make our recruitment, assessment, and selection processes as accessible as possible and provide accommodations as required for applicants with disabilities. If you require any accommodations at any point during the application and hiring process, please contact uoft.careers@utoronto.ca .', '{"About":"the University of Toronto, Department of Paediatric Dentistry, please visit our home page at https://www.dentistry.utoronto.ca Diversity Statement The University of Toronto embraces Diversity and is building a culture of belonging that increases our capacity to effectively address and serve the interests of our global community. We strongly encourage applications from Indigenous Peoples, Black and racialized persons, women, persons with disabilities, and people of diverse sexual and gender identities. We value applicants who have demonstrated a commitment to equity, diversity and inclusion and recognize that diverse perspectives, experiences, and expertise are essential to strengthening our academic mission. Accessibility Statement The University strives to be an equitable and inclusive community and proactively seeks to increase diversity among its community members. Our values regarding equity and diversity are linked with our unwavering commitment to excellence in the pursuit of our academic mission. The University is committed to the principles of the Accessibility for Ontarians with Disabilities Act (AODA). As such, we strive to make our recruitment, assessment, and selection processes as accessible as possible and provide accommodations as required for applicants with disabilities. If you require any accommodations at any point during the application and hiring process, please contact uoft.careers@utoronto.ca .","Responsibilities":"include full clinical practice, research, and education, and administrative","Qualifications":"include management proficiency, dispute resolution, communications expertise, mentoring capabilities, the ability to engender trust, function collaboratively with all manner of clinical teams and administration. Additionally, the successful candidate will have a long-term vision for the Department which integrates with the mission of Peri-Operative Services, the Hospital and the University of Toronto. Salary will be in the range of $200,000 to $400,000 for 40 hours per week, commensurate with"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Dentist-in-Chief – Department of Paediatric Dentistry","description":"The Department of Paediatric Dentistry at The Hospital for Sick Children (SickKids), Faculty of Dentistry, University of Toronto, is inviting applications for the position of Dentist-in-Chief. This is a full-time role for an academic paediatric dentist and leader in paediatric oral health. The effective date of this appointment is June 2027 but can be negotiated. Primary Description Responsibilities include full clinical practice, research, and education, and administrative responsibilities as required by a Department Chief. Evidence of excellence in teaching and research is required. This role reports directly to the Chief of Peri-Operative Services. Additional Description The successful candidate should be a senior academic with an international reputation who can provide effective and collaborative leadership and vision at the hospital, provincial, national and international levels. The candidate must be eligible for appointment at the rank of Associate Professor at the University of Toronto and be eligible for certification with the Royal College of Dental Surgeons of Ontario. Candidates must obtain an appropriate Visa, if applicable. We are seeking an individual whose leadership qualifications include management proficiency, dispute resolution, communications expertise, mentoring capabilities, the ability to engender trust, function collaboratively with all manner of clinical teams and administration. Additionally, the successful candidate will have a long-term vision for the Department which integrates with the mission of Peri-Operative Services, the Hospital and the University of Toronto. Salary will be in the range of $200,000 to $400,000 for 40 hours per week, commensurate with qualifications and experience, and which will be supplemented by clinical billing activity. Benefits include Medical, Dental, Life, Group Insurance, Pension, Vision. A per annum stipend, in recognition of the administrative leadership responsibilities associated with the Department Chief role, will be provided. Support for relocation expenses will be offered. The position has a potential duration of two terms of five years each. Department Description The Department of Paediatric Dentistry at The Hospital for Sick Children consist of 18 dental surgeons, orthodontists and paediatric dentists, provides dental care for children and adolescents under 18 years whose treatment is best managed in a multidisciplinary hospital environment. It is integral to the Ontario Cleft Lip and Palate Craniofacial Dental program and is a major clinical training and research centre for the University of Toronto Graduate Paediatric Dentistry program. The Department also provides training to hospital staff, community dentists, physicians and families through affiliation with the University of Toronto. Hospital Description SickKids, located at 555 University Avenue in downtown Toronto, is among the largest children’s hospitals in North America and has a long history of excellence in clinical care, research and education. It was named the number one paediatric hospital in the world in 2025, by Newsweek magazine. SickKids is fully affiliated with the University of Toronto and is located adjacent to the University campus and to numerous specialty hospitals and biomedical research institutes. Toronto is a vibrant and multicultural city, widely recognized as one of the most diverse cities in the world, with approximately half of its residents born outside Canada and representation from more than 250 ethnicities. This diversity is reflected in the city’s neighbourhoods, food scene, Michelin-starred restaurants across Toronto and the surrounding region, and strengths in key sectors such as life sciences, finance, information, and communications technology. As one of the largest cities in North America, Toronto offers a dynamic downtown, diverse neighbourhoods, strong schools, and access to leading universities. It is regularly recognized in global city, travel, and liveability rankings. World-famous lake and wilderness country and year-round outdoor recreation are easily accessible, as are two hub airports for regional and international travel. Application Process Applications will be accepted until October 30, 2026. Should you be interested in this opportunity, please forward a one-page statement of interest [which includes the names and contact information for 3 referees] and curriculum vitae, in PDF format, via email to: Dr. Abhaya V. Kulkarni Chief, Peri-Operative Services and Chair of the Search Committee 175 Elizabeth St, Toronto, ON M5G 2G3 EMAIL: dentistrydepartmentchief.recruitment@sickkids.ca All qualified candidates are encouraged to apply; however, Canadians and permanent residents will be given priority. For more information about the University of Toronto, Department of Paediatric Dentistry, please visit our home page at https://www.dentistry.utoronto.ca Diversity Statement The University of Toronto embraces Diversity and is building a culture of belonging that increases our capacity to effectively address and serve the interests of our global community. We strongly encourage applications from Indigenous Peoples, Black and racialized persons, women, persons with disabilities, and people of diverse sexual and gender identities. We value applicants who have demonstrated a commitment to equity, diversity and inclusion and recognize that diverse perspectives, experiences, and expertise are essential to strengthening our academic mission. Accessibility Statement The University strives to be an equitable and inclusive community and proactively seeks to increase diversity among its community members. Our values regarding equity and diversity are linked with our unwavering commitment to excellence in the pursuit of our academic mission. The University is committed to the principles of the Accessibility for Ontarians with Disabilities Act (AODA). As such, we strive to make our recruitment, assessment, and selection processes as accessible as possible and provide accommodations as required for applicants with disabilities. If you require any accommodations at any point during the application and hiring process, please contact uoft.careers@utoronto.ca .","datePosted":"2026-08-17T00:00:00.000Z","validThrough":"2026-11-15T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"The Hospital for Sick Children"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"555 University Avenue","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5G1X8","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a83ea14bfdb235d5f6bee2c"}}'::jsonb, '2026-10-04T05:15:13.902Z'
)
