INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a7ea2b6bfdb235d5f63bdbf', 'https://physiciancareers.ca/jobs/division-head-haematology-oncology-6a7ea2b6bfdb235d5f63bdbf', 'Division Head, Haematology Oncology', 'Pediatrics', 'full-time', 'The Hospital for Sick Children', 'downtown toronto', 'ON', '555 University Avenue', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'annual', 425000, 525000, 475000, 475000, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-08-13', '2026-11-11', '2026-11-11', '2026-11-11', FALSE, '["sarah.isbester@sickkids.ca"]'::jsonb, '', 'Join our team and be part of our bold new strategy for Precision Child Health, advancing discovery, prevention, and treatment for children worldwide. The Division of Haematology Oncology provides diagnostic services and specialist care for children and adolescents with cancer (paediatric oncology) and nonmalignant blood diseases (paediatric haematology), as well as those receiving haematopoietic stem cell transplantation and cellular therapies. The Division of Hematology Oncology is seeking a full-time permanent faculty position as Division Head, Haematology Oncology at the Hospital for Sick Children, 555 University Ave., Toronto, ON, which is an academic health science centre dedicated to the care of children affiliated with the Temerty Faculty of Medicine at the University of Toronto. The Division offers a comprehensive subspecialty residency /fellowship program, attracting Canadian and international trainees to our Royal College of Physicians and Surgeons of Canada-accredited program in Paediatric Haematology-Oncology. There are also specialized fellowships offered across the division ranging from early phase trials and neuro-oncology to cancer genetics, late effects/survivorship, and stem cell transplantation/cellular therapy. Our interprofessional team provides comprehensive care and services across 5 sections (haematology, stem cell transplant/cellular therapies, leukemia/lymphoma, solid tumour, and neuro-oncology). Specialized multi-disciplinary programs include New Agents and Innovative Therapies (NAIT), Cancer Genetics, Long Term Follow-up, Bone Marrow Failure, Haemoglobinopathies and Thrombosis. We are actively involved in clinical, translational, and basic science research related to blood disorders and cancer in children, with a focus on designing and participating in prospective clinical trials and delivering precision therapies to patients locally, provincially, and nationally. The successful candidate will lead and mentor our diverse faculty and trainees, collaborate with allied health and nursing partners, and innovate with our scientists at the Research Institute. By championing clinical services, education, and research, you will advance our cancer and haematology programs and align academic activities with the Temerty Faculty of Medicine at the University of Toronto. The successful candidate will provide care in both inpatient and ambulatory settings within the Division of Haematology-Oncology. This role supports the expansion of specialized clinical services and offers opportunities for creative and professional activities, as well as translational and basic research to improve evidence-based care. As Division Head, you will also serve as a strategic advisor and steward of philanthropic funds, influencing the Division&#39;s vision and serving as Head of the Garron Family Cancer Centre (GFCC). The GFCC enhances and integrates clinical, research, and educational activities to improve outcomes for children, adolescents, and young adults with cancer. The successful candidate must possess leadership and mentoring experience, with a demonstrated track record in academic and research excellence. The successful candidate will be eligible for an academic appointment at the University of Toronto. Rank and salary ($425,000-$525,000) per annum will be commensurate with qualifications and experience. The successful candidate may also be eligible for a leadership stipend. The successful candidate will be eligible for a benefits package which includes medical, dental, life insurance, long term disability insurance, group insurance, pension plan, vision care, academic allowance, and relocation package and support services. All candidates must be able to function proficiently in English, hold an MD, MBBS or equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable qualifications. Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. This position will remain open until filled. Interested individuals should submit a letter of interest, curriculum vitae including a statement of research, education and clinical contribution, and names and addresses of three references to Dr. Meredith Irwin, Professor and Chair, Department of Paediatrics, The Hospital for Sick Children, 555 University Avenue, Toronto, Ontario Canada M5G 1X8: e-mail sarah.isbester@sickkids.ca The Department is strongly committed to diversity within its community and especially welcomes applications from racialized person/persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ persons, and others who may contribute to the further diversification of ideas. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities. Persons with disabilities who anticipate needing accommodations for any part of the application process may contact, in confidence, sarah.isbester@sickkids.ca', '{"Qualifications":"and experience. The successful candidate may also be eligible for a leadership stipend. The successful candidate will be eligible for a benefits package which includes medical, dental, life insurance, long term disability insurance, group insurance, pension plan, vision care, academic allowance, and relocation package and support services. All candidates must be able to function proficiently in English, hold an MD, MBBS or equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Division Head, Haematology Oncology","description":"Join our team and be part of our bold new strategy for Precision Child Health, advancing discovery, prevention, and treatment for children worldwide. The Division of Haematology Oncology provides diagnostic services and specialist care for children and adolescents with cancer (paediatric oncology) and nonmalignant blood diseases (paediatric haematology), as well as those receiving haematopoietic stem cell transplantation and cellular therapies. The Division of Hematology Oncology is seeking a full-time permanent faculty position as Division Head, Haematology Oncology at the Hospital for Sick Children, 555 University Ave., Toronto, ON, which is an academic health science centre dedicated to the care of children affiliated with the Temerty Faculty of Medicine at the University of Toronto. The Division offers a comprehensive subspecialty residency /fellowship program, attracting Canadian and international trainees to our Royal College of Physicians and Surgeons of Canada-accredited program in Paediatric Haematology-Oncology. There are also specialized fellowships offered across the division ranging from early phase trials and neuro-oncology to cancer genetics, late effects/survivorship, and stem cell transplantation/cellular therapy. Our interprofessional team provides comprehensive care and services across 5 sections (haematology, stem cell transplant/cellular therapies, leukemia/lymphoma, solid tumour, and neuro-oncology). Specialized multi-disciplinary programs include New Agents and Innovative Therapies (NAIT), Cancer Genetics, Long Term Follow-up, Bone Marrow Failure, Haemoglobinopathies and Thrombosis. We are actively involved in clinical, translational, and basic science research related to blood disorders and cancer in children, with a focus on designing and participating in prospective clinical trials and delivering precision therapies to patients locally, provincially, and nationally. The successful candidate will lead and mentor our diverse faculty and trainees, collaborate with allied health and nursing partners, and innovate with our scientists at the Research Institute. By championing clinical services, education, and research, you will advance our cancer and haematology programs and align academic activities with the Temerty Faculty of Medicine at the University of Toronto. The successful candidate will provide care in both inpatient and ambulatory settings within the Division of Haematology-Oncology. This role supports the expansion of specialized clinical services and offers opportunities for creative and professional activities, as well as translational and basic research to improve evidence-based care. As Division Head, you will also serve as a strategic advisor and steward of philanthropic funds, influencing the Division&#39;s vision and serving as Head of the Garron Family Cancer Centre (GFCC). The GFCC enhances and integrates clinical, research, and educational activities to improve outcomes for children, adolescents, and young adults with cancer. The successful candidate must possess leadership and mentoring experience, with a demonstrated track record in academic and research excellence. The successful candidate will be eligible for an academic appointment at the University of Toronto. Rank and salary ($425,000-$525,000) per annum will be commensurate with qualifications and experience. The successful candidate may also be eligible for a leadership stipend. The successful candidate will be eligible for a benefits package which includes medical, dental, life insurance, long term disability insurance, group insurance, pension plan, vision care, academic allowance, and relocation package and support services. All candidates must be able to function proficiently in English, hold an MD, MBBS or equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable qualifications. Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. This position will remain open until filled. Interested individuals should submit a letter of interest, curriculum vitae including a statement of research, education and clinical contribution, and names and addresses of three references to Dr. Meredith Irwin, Professor and Chair, Department of Paediatrics, The Hospital for Sick Children, 555 University Avenue, Toronto, Ontario Canada M5G 1X8: e-mail sarah.isbester@sickkids.ca The Department is strongly committed to diversity within its community and especially welcomes applications from racialized person/persons of colour, women, Indigenous / Aboriginal People of North America, persons with disabilities, LGBTQ persons, and others who may contribute to the further diversification of ideas. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities. Persons with disabilities who anticipate needing accommodations for any part of the application process may contact, in confidence, sarah.isbester@sickkids.ca","datePosted":"2026-08-13T00:00:00.000Z","validThrough":"2026-11-11T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"The Hospital for Sick Children"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"555 University Avenue","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5G1X8","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a7ea2b6bfdb235d5f63bdbf"}}'::jsonb, '2026-10-04T05:15:14.951Z'
)
