INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a780b4dbfdb235d5f59291a', 'https://physiciancareers.ca/jobs/pediatric-endocrinologist-opportunity-multiple-toronto-locations-kidcrew-6a780b4dbfdb235d5f59291a', 'Pediatric Endocrinologist Opportunity Multiple Toronto Locations Kidcrew', 'Pediatrics', 'full-time', 'Kidcrew', 'mississauga', 'ON', '1440 Bathurst St', 'Toronto, ON', 43.589, -79.6441, 22.18, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-08-08', '2026-11-06', '2026-11-06', '2026-11-06', FALSE, '["drdinakulik@gmail.com"]'::jsonb, '', 'Kidcrew is growing and we are looking for a Pediatric Endocrinologist to join our expanding multidisciplinary pediatric team. Opportunity to join the Bathurst, or Duncan Mill locations, or soon-to-open Mississauga or Downtown locations. This is an exciting opportunity to build and grow a pediatric endocrinology practice within an established, collaborative model serving a large and growing patient population. What we offer: &#129658; Flexible opportunities — full-time, part-time, hybrid, and virtual options available &#127973; Established referral base with strong demand &#128105;‍⚕️ Collaborative environment with pediatricians, subspecialists, psychologists, therapists, and allied health professionals &#128200; Opportunity to develop areas of interest and specialized programs ✔ Dedicated administrative and operational support ✔ Leadership and growth opportunities available Kidcrew currently serves 130,000+ children and families and continues to expand across the Greater Toronto Area, with additional locations planned. Whether you are an experienced Pediatric Endocrinologist or are looking to build and shape a growing practice, we would love to connect. For a confidential discussion, please reach out: Dina Kulik, MD Founder &amp; CEO, Kidcrew drdinakulik@gmail.com', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Pediatric Endocrinologist Opportunity Multiple Toronto Locations Kidcrew","description":"Kidcrew is growing and we are looking for a Pediatric Endocrinologist to join our expanding multidisciplinary pediatric team. Opportunity to join the Bathurst, or Duncan Mill locations, or soon-to-open Mississauga or Downtown locations. This is an exciting opportunity to build and grow a pediatric endocrinology practice within an established, collaborative model serving a large and growing patient population. What we offer: &#129658; Flexible opportunities — full-time, part-time, hybrid, and virtual options available &#127973; Established referral base with strong demand &#128105;‍⚕️ Collaborative environment with pediatricians, subspecialists, psychologists, therapists, and allied health professionals &#128200; Opportunity to develop areas of interest and specialized programs ✔ Dedicated administrative and operational support ✔ Leadership and growth opportunities available Kidcrew currently serves 130,000+ children and families and continues to expand across the Greater Toronto Area, with additional locations planned. Whether you are an experienced Pediatric Endocrinologist or are looking to build and shape a growing practice, we would love to connect. For a confidential discussion, please reach out: Dina Kulik, MD Founder &amp; CEO, Kidcrew drdinakulik@gmail.com","datePosted":"2026-08-08T00:00:00.000Z","validThrough":"2026-11-06T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Kidcrew"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1440 Bathurst St","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5R3J3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a780b4dbfdb235d5f59291a"}}'::jsonb, '2026-10-04T05:15:15.975Z'
)
