INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a74177d996e67ca991f2083', 'https://physiciancareers.ca/jobs/consultant-pediatrician-locum-opportunity-6a74177d996e67ca991f2083', 'Consultant Pediatrician – Locum Opportunity', 'Pediatrics', 'locum', 'Mimico Medical Clinic', 'etobicoke', 'ON', '398 Royal York Road', 'Toronto, ON', 43.6205, -79.5132, 11.08, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, TRUE, FALSE, NULL, '2026-08-05', '2026-10-31', '2026-10-31', '2026-10-31', FALSE, '[]'::jsonb, '', 'Consultant Pediatrician – Locum Opportunity (Toronto, Ontario) We are seeking a Consultant Pediatrician to provide parental leave coverage from October 2026 to October 2027, with the opportunity to remain on as an associate following the locum period, if desired. This is an excellent opportunity to join a modern, well-established community practice with a strong referral base and the flexibility to build a practice that aligns with your professional interests. What we offer: Modern, clean, and bright clinical space Supportive, collegial, multidisciplinary environment including family medicine, subspecialty medicine, mental health, and allied health professionals Full-service administrative support Advanced technology including OSCAR Pro EMR, Ocean eReferrals, and AI scribe tools Established referral network that can support a busy practice from day one Flexible scheduling with the ability to set your own hours Extremely competitive income split Free parking and easy access via public transit Practice Profile The current practice is a 100% consultative pediatric practice with a mix of medical, developmental, and mental health consultations. Follow-up care is provided at the discretion of the consultant pediatrician. For physicians interested in continuing beyond the locum period, there is an opportunity to remain as an associate and further develop the practice based on individual interests, including focused areas of pediatrics, developmental care, mental health, or primary care services. Located in the vibrant Mimico community of Toronto, this opportunity combines professional flexibility, strong clinical support, and immediate access to a well-established patient base. Requirements: Board certification in Pediatrics CPSO license in Pediatrics Excellent communication skills for effective collaboration with medical teams. Commitment to delivering high-quality, patient-centered care. Why Mimico Medical? Physician-owned and operated. State-of-the-art medical facilities with advanced technology. Supportive work environment prioritizing physician quality of life. Opportunities for professional growth and autonomy. Full management support from an experienced team. Competitive compensation and billing support. About Us Mimico Medical is a growing multidisciplinary medical clinic proudly serving the Etobicoke community with comprehensive, patient-centered healthcare. Our team includes 9 Family Physicians operating under the FHO+ care model , supported by a robust internal referral network and allied health services, including Psychiatry, Psychotherapy, Physiotherapy, Pediatrics, Women&#39;s Health, and other specialty clinics. As we continue to expand our services, we are committed to improving access to high-quality, collaborative care for our patients.', '{"About":"Us Mimico Medical is a growing multidisciplinary medical clinic proudly serving the Etobicoke community with comprehensive, patient-centered healthcare. Our team includes 9 Family Physicians operating under the FHO+ care model , supported by a robust internal referral network and allied health services, including Psychiatry, Psychotherapy, Physiotherapy, Pediatrics, Women&#39;s Health, and other specialty clinics. As we continue to expand our services, we are committed to improving access to high-quality, collaborative care for our patients."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Consultant Pediatrician – Locum Opportunity","description":"Consultant Pediatrician – Locum Opportunity (Toronto, Ontario) We are seeking a Consultant Pediatrician to provide parental leave coverage from October 2026 to October 2027, with the opportunity to remain on as an associate following the locum period, if desired. This is an excellent opportunity to join a modern, well-established community practice with a strong referral base and the flexibility to build a practice that aligns with your professional interests. What we offer: Modern, clean, and bright clinical space Supportive, collegial, multidisciplinary environment including family medicine, subspecialty medicine, mental health, and allied health professionals Full-service administrative support Advanced technology including OSCAR Pro EMR, Ocean eReferrals, and AI scribe tools Established referral network that can support a busy practice from day one Flexible scheduling with the ability to set your own hours Extremely competitive income split Free parking and easy access via public transit Practice Profile The current practice is a 100% consultative pediatric practice with a mix of medical, developmental, and mental health consultations. Follow-up care is provided at the discretion of the consultant pediatrician. For physicians interested in continuing beyond the locum period, there is an opportunity to remain as an associate and further develop the practice based on individual interests, including focused areas of pediatrics, developmental care, mental health, or primary care services. Located in the vibrant Mimico community of Toronto, this opportunity combines professional flexibility, strong clinical support, and immediate access to a well-established patient base. Requirements: Board certification in Pediatrics CPSO license in Pediatrics Excellent communication skills for effective collaboration with medical teams. Commitment to delivering high-quality, patient-centered care. Why Mimico Medical? Physician-owned and operated. State-of-the-art medical facilities with advanced technology. Supportive work environment prioritizing physician quality of life. Opportunities for professional growth and autonomy. Full management support from an experienced team. Competitive compensation and billing support. About Us Mimico Medical is a growing multidisciplinary medical clinic proudly serving the Etobicoke community with comprehensive, patient-centered healthcare. Our team includes 9 Family Physicians operating under the FHO+ care model , supported by a robust internal referral network and allied health services, including Psychiatry, Psychotherapy, Physiotherapy, Pediatrics, Women&#39;s Health, and other specialty clinics. As we continue to expand our services, we are committed to improving access to high-quality, collaborative care for our patients.","datePosted":"2026-08-05T00:00:00.000Z","validThrough":"2026-10-31T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Mimico Medical Clinic"},"employmentType":"locum","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"398 Royal York Road","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M8Y2R5","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a74177d996e67ca991f2083"}}'::jsonb, '2026-10-04T05:15:22.180Z'
)
