INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a7173a9996e67ca9919b0d6', 'https://physiciancareers.ca/jobs/kidcrew-welcome-pediatricians-and-pediatric-subspecialists-6a7173a9996e67ca9919b0d6', 'KIDCREW - Welcome Pediatricians and Pediatric Subspecialists!', 'Pediatrics', 'full-time', 'Kidcrew', 'north york', 'ON', '240 Duncan Mill Road', 'Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, TRUE, FALSE, NULL, '2026-08-03', '2026-11-01', '2026-11-01', '2026-11-01', FALSE, '["DrDinaKulik@gmail.com"]'::jsonb, '', 'WELCOME TO KIDCREW! Canada&#39;s Largest Multidisciplinary Kids&#39; Health Clinic. We are eager to welcome additional PEDIATRICIANS and PEDIATRIC SUB-SPECIALISTS . Full-time, part-time, long term or contract Two clinic locations Bathurst and St Clair, midtown Toronto Duncan Mill Road, North York, Toronto New, beautiful, bright, entertaining and technologically advanced clinics. Kidcrew is an award-winning multidisciplinary pediatric practice in Toronto, Ontario. The clinics are bright and welcoming, with state-of-the-art technology to improve efficiency and communication between team members. Our diverse team of general pediatricians, pediatric subspecialists, mental health practitioners and allied health care providers work together to provide comprehensive and collaborative care. - Work in the office and/or virtually. You choose. - Our virtual-care model allows doctors to augment with casual, part-time, or full-time work. - Cloud-based, HIPAA/PHIPA compliant EMR with VPN access from home. - Chart, bill, order labs/imaging/write sick notes/referrals and discharge notes from anywhere you want! - Guaranteed patient volume depending on preference. - ZERO EMR fee. - Competitive overhead rate. - Overhead is tax-deductible as an associate (versus an employee at other clinics). - Commitment is casual or long-term. You can pick up as much or as little as you want. It&#39;s up to you when you want to work, how long, and how frequently you see patients. - The offices are brand new. The EMR is PS Suite (Telus). - Our professional office staff handles all the administrative tasks. - Incredible nursing support. - Flexible patient encounters sick visits, consults or follow-ups, in person or via virtual medicine. - Flexibility in hours: the ability to work part-time, FT, evenings, or weekends - Work alongside specialists – Kidcrew is multidisciplinary and collaborative. - Attractive fee split Requirement: CPSO licensed This is an excellent opportunity to build or relocate a practice in a highly populated residential area. The clinic is open seven days a week. 365 days a year. **New Graduates Encouraged to Apply** About Kidcrew At Kidcrew, we have created an award-winning, forward-thinking and innovative children&#39;s clinic focusing on family-centred care and wellness for children of all ages. We are passionate about providing quality pediatric care for kids and families. From our friendly front desk staff to our non-traditional 2,000-square-foot patient lounge with a playground, iPad stations, and a playroom, Kidcrew is committed to providing an exceptional patient experience. We have over 130 clinicians on our team: pediatricians, a variety of pediatric sub-specialists, dietitians, speech-language pathologists, physiotherapists, occupational therapists, psychologists, and others who provide a comprehensive and collaborative model under one roof. This is an excellent opportunity for new grads and seasoned pediatricians looking to join a multidisciplinary, collaborative practice without having to manage day-to-day operations. Thank you very much for your time. We welcome you to join us on our journey to reinventing kids&#39; healthcare. Stay healthy and safe! Dr. Dina Kulik DrDinaKulik@gmail.com https://kidcrew.com/', '{"About":"Kidcrew At Kidcrew, we have created an award-winning, forward-thinking and innovative children&#39;s clinic focusing on family-centred care and wellness for children of all ages. We are passionate"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"KIDCREW - Welcome Pediatricians and Pediatric Subspecialists!","description":"WELCOME TO KIDCREW! Canada&#39;s Largest Multidisciplinary Kids&#39; Health Clinic. We are eager to welcome additional PEDIATRICIANS and PEDIATRIC SUB-SPECIALISTS . Full-time, part-time, long term or contract Two clinic locations Bathurst and St Clair, midtown Toronto Duncan Mill Road, North York, Toronto New, beautiful, bright, entertaining and technologically advanced clinics. Kidcrew is an award-winning multidisciplinary pediatric practice in Toronto, Ontario. The clinics are bright and welcoming, with state-of-the-art technology to improve efficiency and communication between team members. Our diverse team of general pediatricians, pediatric subspecialists, mental health practitioners and allied health care providers work together to provide comprehensive and collaborative care. - Work in the office and/or virtually. You choose. - Our virtual-care model allows doctors to augment with casual, part-time, or full-time work. - Cloud-based, HIPAA/PHIPA compliant EMR with VPN access from home. - Chart, bill, order labs/imaging/write sick notes/referrals and discharge notes from anywhere you want! - Guaranteed patient volume depending on preference. - ZERO EMR fee. - Competitive overhead rate. - Overhead is tax-deductible as an associate (versus an employee at other clinics). - Commitment is casual or long-term. You can pick up as much or as little as you want. It&#39;s up to you when you want to work, how long, and how frequently you see patients. - The offices are brand new. The EMR is PS Suite (Telus). - Our professional office staff handles all the administrative tasks. - Incredible nursing support. - Flexible patient encounters sick visits, consults or follow-ups, in person or via virtual medicine. - Flexibility in hours: the ability to work part-time, FT, evenings, or weekends - Work alongside specialists – Kidcrew is multidisciplinary and collaborative. - Attractive fee split Requirement: CPSO licensed This is an excellent opportunity to build or relocate a practice in a highly populated residential area. The clinic is open seven days a week. 365 days a year. **New Graduates Encouraged to Apply** About Kidcrew At Kidcrew, we have created an award-winning, forward-thinking and innovative children&#39;s clinic focusing on family-centred care and wellness for children of all ages. We are passionate about providing quality pediatric care for kids and families. From our friendly front desk staff to our non-traditional 2,000-square-foot patient lounge with a playground, iPad stations, and a playroom, Kidcrew is committed to providing an exceptional patient experience. We have over 130 clinicians on our team: pediatricians, a variety of pediatric sub-specialists, dietitians, speech-language pathologists, physiotherapists, occupational therapists, psychologists, and others who provide a comprehensive and collaborative model under one roof. This is an excellent opportunity for new grads and seasoned pediatricians looking to join a multidisciplinary, collaborative practice without having to manage day-to-day operations. Thank you very much for your time. We welcome you to join us on our journey to reinventing kids&#39; healthcare. Stay healthy and safe! Dr. Dina Kulik DrDinaKulik@gmail.com https://kidcrew.com/","datePosted":"2026-08-03T00:00:00.000Z","validThrough":"2026-11-01T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Kidcrew"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"240 Duncan Mill Road","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M3B3S6","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a7173a9996e67ca9919b0d6"}}'::jsonb, '2026-10-04T05:15:23.051Z'
)
