) VALUES (
  '6a7173a9996e67ca9919b0b8', 'https://physiciancareers.ca/jobs/pediatric-endocrinologist-opportunity-multiple-toronto-locations-kidcrew-6a7173a9996e67ca9919b0b8', 'Pediatric Endocrinologist Opportunity Multiple Toronto Locations Kidcrew', 'Pediatrics', 'full-time', 'Kidcrew', 'north york', 'ON', '240 Duncan Mill Road', 'Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-08-03', '2026-11-01', '2026-11-01', '2026-11-01', FALSE, '["drdinakulik@gmail.com"]'::jsonb, '', 'Kidcrew is growing and we are looking for a Pediatric Endocrinologist to join our expanding multidisciplinary pediatric team. This is an exciting opportunity to build and grow a pediatric endocrinology practice within an established, collaborative model serving a large and growing patient population. What we offer: &#129658; Flexible opportunities — full-time, part-time, hybrid, and virtual options available &#127973; Established referral base with strong demand &#128105;‍⚕️ Collaborative environment with pediatricians, subspecialists, psychologists, therapists, and allied health professionals &#128200; Opportunity to develop areas of interest and specialized programs ✔ Dedicated administrative and operational support ✔ Leadership and growth opportunities available Kidcrew currently serves 120,000+ children and families and continues to expand across the Greater Toronto Area, with additional locations planned. Whether you are an experienced Pediatric Endocrinologist or are looking to build and shape a growing practice, we would love to connect. For a confidential discussion, please reach out: Dina Kulik, MD Founder &amp; CEO, Kidcrew drdinakulik@gmail.com', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Pediatric Endocrinologist Opportunity Multiple Toronto Locations Kidcrew","description":"Kidcrew is growing and we are looking for a Pediatric Endocrinologist to join our expanding multidisciplinary pediatric team. This is an exciting opportunity to build and grow a pediatric endocrinology practice within an established, collaborative model serving a large and growing patient population. What we offer: &#129658; Flexible opportunities — full-time, part-time, hybrid, and virtual options available &#127973; Established referral base with strong demand &#128105;‍⚕️ Collaborative environment with pediatricians, subspecialists, psychologists, therapists, and allied health professionals &#128200; Opportunity to develop areas of interest and specialized programs ✔ Dedicated administrative and operational support ✔ Leadership and growth opportunities available Kidcrew currently serves 120,000+ children and families and continues to expand across the Greater Toronto Area, with additional locations planned. Whether you are an experienced Pediatric Endocrinologist or are looking to build and shape a growing practice, we would love to connect. For a confidential discussion, please reach out: Dina Kulik, MD Founder &amp; CEO, Kidcrew drdinakulik@gmail.com","datePosted":"2026-08-03T00:00:00.000Z","validThrough":"2026-11-01T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Kidcrew"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"240 Duncan Mill Road","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M3B3S6","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a7173a9996e67ca9919b0b8"}}'::jsonb, '2026-10-04T05:15:23.948Z'
)
