INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a7173a9996e67ca9919b0ae', 'https://physiciancareers.ca/jobs/gatroenterologist-for-busy-community-pediatric-practice-6a7173a9996e67ca9919b0ae', 'GATROENTEROLOGIST for busy community pediatric practice', 'Pediatrics', 'full-time', 'Kidcrew', 'north york', 'ON', '1440 Bathurst St', 'Toronto, ON', 43.7615, -79.4111, 12.25, NULL, 'hourly', 500, 500, 500, 1000000, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, TRUE, FALSE, NULL, '2026-08-03', '2026-11-01', '2026-11-01', '2026-11-01', FALSE, '["drdina@kidcrew.com"]'::jsonb, '', 'GASTROENTEROLOGIST, full-time or part-time, wanted for a multi-disciplinary clinic at either Kidcrew location. Midtown: Bathurst and St Clair North York: Leslie and 401 DAYTIME OR AFTER-HOURS POSITIONS AVAILABLE The offices are brand new. The EMR is PS Suite (Telus). Our professional office staff handles all the administrative tasks. Kidcrew is an award-winning multi-disciplinary pediatric practice located in Midtown Toronto and North York. We have over 80,000 patients. Our Virtual Care Clinic serves kids from anywhere in Ontario. Our virtual-care model provides flexibility to allow doctors to augment with casual, part-time, or full-time work. Cloud-based, HIPAA/PHIPA compliant EMR with VPN access from home. Chart, bill, order labs/imaging/write sick notes/referrals and discharge notes from anywhere you want! Guaranteed patient volume (4-6/hr) depending on preference. ZERO EMR fee. Competitive overhead rate. Overhead is tax-deductible as an associate (versus an employee at other clinics). Bill upwards of $500/hour Commitment is casual or long-term. You can pick up as much or as little as you want. When you want to work, how long, and how frequently you see patients, it&#39;s up to you. Our professional office staff handles all the administrative tasks. Who do we serve? We can see patients from anywhere in Ontario, including in rural, northern, and underserviced areas. Telemedicine can improve the health and well-being of patients who have poor access to care or can only use the ER. We can help improve access and, therefore, patients&#39; overall health and well-being in these areas. We are thrilled to help more families with timely expert pediatric care. Patient Follow Up Kidcrew clinicians collaborate to ensure patients have timely and accessible follow-up, in order to avoid unnecessary emergency room use and ensure continuity of care. Flexible patient encounters : urgent visits, consults or follow-ups, in person or via virtual medicine. Flexibility in hours : the ability to work part-time, FT, evenings, or weekends Work alongside specialists: with over 20 different medical and surgical specialties affiliated Attractive fee split Requirement: CPSO licensed This is an excellent opportunity to build or relocate a practice in a highly populated residential area. The clinic is open seven days a week. **New Graduates Encouraged to Apply** About Kidcrew At Kidcrew, we have created forward-thinking and innovative children&#39;s clinics focusing on family-centred care and wellness for children of all ages. We are looking to bring on excellent, eager, and friendly pediatricians and specialists. Pediatricians will provide well-baby care, sick visits, and general pediatrics to this thriving community. In addition, the clinic provides nursing care. We are passionate about providing quality pediatric care for kids and families. A state-of-the-art EMR is used along with well-qualified friendly, trained support staff. From our friendly front desk staff to our non-traditional 2,000 square-foot patient lounges with a playground, iPad stations, and a playroom, Kidcrew is committed to providing an exceptional patient experience. We have over 120 clinicians on our team: pediatricians, a variety of pediatric sub-specialists, dietitians, speech-language pathologists, physiotherapists, occupational therapists, psychologists, and others to provide a comprehensive and collaborative model under one roof. Join us on our journey to reinventing kids&#39; healthcare. https://kidcrew.com/ Our founder, Dr Dina Kulik, is happy to review opportunities at drdina@kidcrew.com', '{"About":"Kidcrew At Kidcrew, we have created forward-thinking and innovative children&#39;s clinics focusing on family-centred care and wellness for children of all ages. We are looking to bring on excellent, eager, and friendly pediatricians and specialists. Pediatricians will provide well-baby care, sick visits, and general pediatrics to this thriving community. In addition, the clinic provides nursing care. We are passionate"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"GATROENTEROLOGIST for busy community pediatric practice","description":"GASTROENTEROLOGIST, full-time or part-time, wanted for a multi-disciplinary clinic at either Kidcrew location. Midtown: Bathurst and St Clair North York: Leslie and 401 DAYTIME OR AFTER-HOURS POSITIONS AVAILABLE The offices are brand new. The EMR is PS Suite (Telus). Our professional office staff handles all the administrative tasks. Kidcrew is an award-winning multi-disciplinary pediatric practice located in Midtown Toronto and North York. We have over 80,000 patients. Our Virtual Care Clinic serves kids from anywhere in Ontario. Our virtual-care model provides flexibility to allow doctors to augment with casual, part-time, or full-time work. Cloud-based, HIPAA/PHIPA compliant EMR with VPN access from home. Chart, bill, order labs/imaging/write sick notes/referrals and discharge notes from anywhere you want! Guaranteed patient volume (4-6/hr) depending on preference. ZERO EMR fee. Competitive overhead rate. Overhead is tax-deductible as an associate (versus an employee at other clinics). Bill upwards of $500/hour Commitment is casual or long-term. You can pick up as much or as little as you want. When you want to work, how long, and how frequently you see patients, it&#39;s up to you. Our professional office staff handles all the administrative tasks. Who do we serve? We can see patients from anywhere in Ontario, including in rural, northern, and underserviced areas. Telemedicine can improve the health and well-being of patients who have poor access to care or can only use the ER. We can help improve access and, therefore, patients&#39; overall health and well-being in these areas. We are thrilled to help more families with timely expert pediatric care. Patient Follow Up Kidcrew clinicians collaborate to ensure patients have timely and accessible follow-up, in order to avoid unnecessary emergency room use and ensure continuity of care. Flexible patient encounters : urgent visits, consults or follow-ups, in person or via virtual medicine. Flexibility in hours : the ability to work part-time, FT, evenings, or weekends Work alongside specialists: with over 20 different medical and surgical specialties affiliated Attractive fee split Requirement: CPSO licensed This is an excellent opportunity to build or relocate a practice in a highly populated residential area. The clinic is open seven days a week. **New Graduates Encouraged to Apply** About Kidcrew At Kidcrew, we have created forward-thinking and innovative children&#39;s clinics focusing on family-centred care and wellness for children of all ages. We are looking to bring on excellent, eager, and friendly pediatricians and specialists. Pediatricians will provide well-baby care, sick visits, and general pediatrics to this thriving community. In addition, the clinic provides nursing care. We are passionate about providing quality pediatric care for kids and families. A state-of-the-art EMR is used along with well-qualified friendly, trained support staff. From our friendly front desk staff to our non-traditional 2,000 square-foot patient lounges with a playground, iPad stations, and a playroom, Kidcrew is committed to providing an exceptional patient experience. We have over 120 clinicians on our team: pediatricians, a variety of pediatric sub-specialists, dietitians, speech-language pathologists, physiotherapists, occupational therapists, psychologists, and others to provide a comprehensive and collaborative model under one roof. Join us on our journey to reinventing kids&#39; healthcare. https://kidcrew.com/ Our founder, Dr Dina Kulik, is happy to review opportunities at drdina@kidcrew.com","datePosted":"2026-08-03T00:00:00.000Z","validThrough":"2026-11-01T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Kidcrew"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1440 Bathurst St","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5R3J3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a7173a9996e67ca9919b0ae"}}'::jsonb, '2026-10-04T05:15:24.840Z'
)
