INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a6adc6b996e67ca990dbffd', 'https://physiciancareers.ca/jobs/staff-echocardiographer-cardiologist-6a6adc6b996e67ca990dbffd', 'Staff Echocardiographer Cardiologist', 'Pediatrics', 'full-time', 'The Hospital for Sick Children', 'downtown toronto', 'ON', '555 University Avenue', 'Toronto, ON', 43.6532, -79.3832, 0, NULL, 'annual', 300000, 450000, 375000, 375000, NULL, NULL, NULL, NULL, NULL, NULL, TRUE, FALSE, FALSE, TRUE, FALSE, NULL, '2026-07-29', '2026-10-27', '2026-10-27', '2026-10-27', FALSE, '["mike.seed@sickkids.ca","meagan.cameira@sickkids.ca"]'::jsonb, '', 'Staff Paediatric Cardiologist Effective immediately The Division of Cardiology at The Hospital for Sick Children, Department of Paediatrics (555 University Ave. Toronto, M5G 1X9), an academic health science centre dedicated exclusively to children, affiliated with the University of Toronto, is seeking a full-time permanent faculty position for a staff paediatric cardiologist with sub-specialty training in Echocardiography at the Labatt Family Heart Centre – Cardiology Division. Candidates with expertise in Fetal Cardiology or Pulmonary Hypertension would be of special interest. The Labatt Family Heart Centre brings together significant interdisciplinary and inter-professional activities within Paediatric Cardiology, Cardiovascular (CV) Surgery, Cardiac Critical Care, Cardiovascular Research and Adult Congenital Heart Disease Programs, thus allowing the Heart Centre to address the needs of patients and families from fetal life to adulthood. The Heart Centre at The Hospital for Sick Children promotes these activities through seamless integration of research activities, academic performance, and exemplary clinical care. The primary role of the successful candidate will be to focus on providing excellence in clinical care, education, and research in the field of Echocardiography. The successful candidate will also be expected to teach our fellows and undertake innovative and impactful research. We anticipate some requirement for additional service provision in other subspecialty areas, including general inpatient and outpatient cardiology, depending on the candidate’s experience and interests. The successful applicant would ideally have completed subspecialty training and/or specific clinical experience in echocardiography and fetal cardiology and will report to the Division Head, Labatt Family Heart Centre. The successful candidate must be able to function proficiently in English, hold an MD, MBBS or the equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable qualifications. Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. The successful candidate must be eligible for an academic appointment at the University of Toronto. Rank and salary ($300,000-$450,000) per annum and will be commensurate with qualifications and experience. Applications should include a cover letter, curriculum vitae and a statement outlining current and future clinical and research interests. In addition, provide names and addresses of three references to Dr. Mike Seed, Head, Division of Cardiology, Department of Paediatrics, Hospital for Sick Children 555 University Avenue, Toronto, Ontario, Canada M5G 1X8 email: mike.seed@sickkids.ca For additional information regarding the Department of Paediatrics see http://www.sickkids.ca/paediatrics/ . The University of Toronto and The Hospital for Sick Children are strongly committed to diversity within its community. Both institutions recognize systemic barriers that impact equity seeking groups. As such, we welcome applications from historically marginalized groups including Black, Indigenous, and Racialized people, women, LGBTQIA+, and/or persons with disabilities. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities. Persons with disabilities who anticipate needing accommodations for any part of the application process may contact, in confidence, Anna Capizzano, r at meagan.cameira@sickkids.ca or 416.613.6122. All qualified applicants are encouraged to apply; however, in accordance with Canadian immigration requirements, Canadians and permanent residents will be given priority. Only those applicants selected for the interview will be contacted.', '{"Qualifications":". Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. The successful candidate must be eligible for an academic appointment at the University of Toronto. Rank and salary ($300,000-$450,000) per annum and will be commensurate with","Additional Information":"regarding the Department of Paediatrics see http://www.sickkids.ca/paediatrics/ . The University of Toronto and The Hospital for Sick Children are strongly committed to diversity within its community. Both institutions recognize systemic barriers that impact equity seeking groups. As such, we welcome applications from historically marginalized groups including Black, Indigenous, and Racialized people, women, LGBTQIA+, and/or persons with disabilities. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities. Persons with disabilities who anticipate needing accommodations for any part of the application process may contact, in confidence, Anna Capizzano, r at meagan.cameira@sickkids.ca or 416.613.6122. All qualified applicants are encouraged to apply; however, in accordance with Canadian immigration requirements, Canadians and permanent residents will be given priority. Only those applicants selected for the interview will be contacted."}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Staff Echocardiographer Cardiologist","description":"Staff Paediatric Cardiologist Effective immediately The Division of Cardiology at The Hospital for Sick Children, Department of Paediatrics (555 University Ave. Toronto, M5G 1X9), an academic health science centre dedicated exclusively to children, affiliated with the University of Toronto, is seeking a full-time permanent faculty position for a staff paediatric cardiologist with sub-specialty training in Echocardiography at the Labatt Family Heart Centre – Cardiology Division. Candidates with expertise in Fetal Cardiology or Pulmonary Hypertension would be of special interest. The Labatt Family Heart Centre brings together significant interdisciplinary and inter-professional activities within Paediatric Cardiology, Cardiovascular (CV) Surgery, Cardiac Critical Care, Cardiovascular Research and Adult Congenital Heart Disease Programs, thus allowing the Heart Centre to address the needs of patients and families from fetal life to adulthood. The Heart Centre at The Hospital for Sick Children promotes these activities through seamless integration of research activities, academic performance, and exemplary clinical care. The primary role of the successful candidate will be to focus on providing excellence in clinical care, education, and research in the field of Echocardiography. The successful candidate will also be expected to teach our fellows and undertake innovative and impactful research. We anticipate some requirement for additional service provision in other subspecialty areas, including general inpatient and outpatient cardiology, depending on the candidate’s experience and interests. The successful applicant would ideally have completed subspecialty training and/or specific clinical experience in echocardiography and fetal cardiology and will report to the Division Head, Labatt Family Heart Centre. The successful candidate must be able to function proficiently in English, hold an MD, MBBS or the equivalent thereto and be certified or eligible for certification by the Royal College of Physicians and Surgeons of Canada or have comparable qualifications. Candidates must hold or be eligible for licensure with the College of Physicians and Surgeons of Ontario. The successful candidate must be eligible for an academic appointment at the University of Toronto. Rank and salary ($300,000-$450,000) per annum and will be commensurate with qualifications and experience. Applications should include a cover letter, curriculum vitae and a statement outlining current and future clinical and research interests. In addition, provide names and addresses of three references to Dr. Mike Seed, Head, Division of Cardiology, Department of Paediatrics, Hospital for Sick Children 555 University Avenue, Toronto, Ontario, Canada M5G 1X8 email: mike.seed@sickkids.ca For additional information regarding the Department of Paediatrics see http://www.sickkids.ca/paediatrics/ . The University of Toronto and The Hospital for Sick Children are strongly committed to diversity within its community. Both institutions recognize systemic barriers that impact equity seeking groups. As such, we welcome applications from historically marginalized groups including Black, Indigenous, and Racialized people, women, LGBTQIA+, and/or persons with disabilities. The Department recognizes and fairly considers the impact of leaves (e.g., family care or health-related) that may contribute to career interruptions or slowdowns. Candidates are encouraged to signal any leave that affected productivity, or that may have influenced their career path. This information will be considered to ensure the equitable assessment of the candidate’s record. The Department further supports an employment equity program and encourages members of designated equity groups to self-identify. It further seeks to ensure equitable treatment and full inclusion of persons with disabilities. Persons with disabilities who anticipate needing accommodations for any part of the application process may contact, in confidence, Anna Capizzano, r at meagan.cameira@sickkids.ca or 416.613.6122. All qualified applicants are encouraged to apply; however, in accordance with Canadian immigration requirements, Canadians and permanent residents will be given priority. Only those applicants selected for the interview will be contacted.","datePosted":"2026-07-29T00:00:00.000Z","validThrough":"2026-10-27T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"The Hospital for Sick Children"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"555 University Avenue","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5G1X8","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a6adc6b996e67ca990dbffd"}}'::jsonb, '2026-10-04T05:15:25.792Z'
)
