INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a5321c0df36206c308be9c9', 'https://physiciancareers.ca/jobs/pediatrician-fullpart-time-6a5321c0df36206c308be9c9', 'Pediatrician - Full/Part Time', 'Pediatrics', 'full-time', 'Bloorkids', 'bloor', 'ON', '622 Bloor Street West', 'Toronto, ON', 43.6685, -79.39, 1.79, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-07-10', '2026-10-08', '2026-10-08', '2026-10-08', FALSE, '[]'::jsonb, '', 'Pediatric clinic at Bathurst and Bloor. This 49-room facility is one of the largest in Toronto with a full complement of General Pediatricians, Subspecialists and Allied Health Providers. It is centrally located downtown and close to transit. You will have the unique opportunity to join a dynamic group of Pediatricians who are committed to outstanding personal and collaborative practice. We are looking for Pediatricians who are interested in a mix of primary/consultant-based pediatric practice. Part-time/Full-time opportunities exist. Compensation includes competitive fee-split and opportunity for profit-sharing (please inquire for more details) This medical facility is well equipped for this pandemic and beyond. Building infection control measures: One way traffic with multiple entrances/exits with additional separate staff entrance The entire building has operating-room quality air exchanges in addition to HEPA filtration Artificial intelligent system for rooming patients And more!', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Pediatrician - Full/Part Time","description":"Pediatric clinic at Bathurst and Bloor. This 49-room facility is one of the largest in Toronto with a full complement of General Pediatricians, Subspecialists and Allied Health Providers. It is centrally located downtown and close to transit. You will have the unique opportunity to join a dynamic group of Pediatricians who are committed to outstanding personal and collaborative practice. We are looking for Pediatricians who are interested in a mix of primary/consultant-based pediatric practice. Part-time/Full-time opportunities exist. Compensation includes competitive fee-split and opportunity for profit-sharing (please inquire for more details) This medical facility is well equipped for this pandemic and beyond. Building infection control measures: One way traffic with multiple entrances/exits with additional separate staff entrance The entire building has operating-room quality air exchanges in addition to HEPA filtration Artificial intelligent system for rooming patients And more!","datePosted":"2026-07-10T00:00:00.000Z","validThrough":"2026-10-08T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Bloorkids"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"622 Bloor Street West","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M6G1K7","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a5321c0df36206c308be9c9"}}'::jsonb, '2026-10-04T05:15:26.828Z'
)
