  '6aa38ecf5ffbbbfeb634f5c8', 'https://physiciancareers.ca/jobs/psychiatry-opportunity-in-busy-forest-hill-practice-6aa38ecf5ffbbbfeb634f5c8', 'Psychiatry Opportunity in Busy Forest Hill Practice', 'Psychiatry', 'full-time', 'Watson Medical', 'forest hill', 'ON', '561 Eglinton Avenue West', 'Toronto, ON', 43.698, -79.412, 5.49, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, TRUE, FALSE, TRUE, FALSE, NULL, '2026-09-10', '2026-10-30', '2026-10-30', '2026-10-30', FALSE, '[]'::jsonb, '', 'Psychiatrists (CPSO Licensed), full-time or part-time, wanted for a busy multi-disciplinary medical practice in Forest Hill, Toronto (Eglinton and Avenue Road). The area supports a robust practice in addition to internal referrals from our family physicians and specialists. The EMR is PS Suite (Telus). Our professional office staff handles all the administrative tasks, including billing. We are open 6 days a week. Service Offerings: Flexibility in hours : the ability to work full time, part-time or weekends Work alongside specialists: with multiple affiliated medical and surgical specialists Attractive fee split Guaranteed minimum hourly wage The position is currently available.', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Psychiatry Opportunity in Busy Forest Hill Practice","description":"Psychiatrists (CPSO Licensed), full-time or part-time, wanted for a busy multi-disciplinary medical practice in Forest Hill, Toronto (Eglinton and Avenue Road). The area supports a robust practice in addition to internal referrals from our family physicians and specialists. The EMR is PS Suite (Telus). Our professional office staff handles all the administrative tasks, including billing. We are open 6 days a week. Service Offerings: Flexibility in hours : the ability to work full time, part-time or weekends Work alongside specialists: with multiple affiliated medical and surgical specialists Attractive fee split Guaranteed minimum hourly wage The position is currently available.","datePosted":"2026-09-10T00:00:00.000Z","validThrough":"2026-10-30T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Watson Medical"},"employmentType":"full-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"561 Eglinton Avenue West","addressLocality":"Toronto","addressRegion":"ON","postalCode":"M5N1B5","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6aa38ecf5ffbbbfeb634f5c8"}}'::jsonb, '2026-10-04T05:15:38.323Z'
)
