INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a87ddd881b073648d717deb', 'https://physiciancareers.ca/jobs/part-time-psychiatrist-virtual-consultations-6a87ddd881b073648d717deb', 'Part-Time Psychiatrist – (Virtual Consultations)', 'Psychiatry', 'part-time', 'Comprehensive Treatment Clinic', 'danforth', 'ON', '1154 Danforth Avenue', 'Old Toronto, ON', 43.6865, -79.33, 5.66, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-08-20', '2026-11-18', '2026-11-18', '2026-11-18', FALSE, '["admin@ctctoronto.com"]'::jsonb, '', 'Part-Time Psychiatrist – (Virtual Consultations) Flexible Remote Opportunity | Competitive Compensation Hybrid of OHIP + Stipend Our outpatient community Rapid Access Addiction Medicine (RAAM) clinic is actively seeking a psychiatrist to join our team on a part-time, virtual basis. This is an ideal opportunity for a psychiatrist who wants to fit meaningful, well-compensated clinical work into an existing schedule. We offer the flexibility to choose when to see patients . Since most patients are admitted to a residential treatment facility, consults can fit throughout your day (e.g., during a no-show to your regular practice), ensuring no lost income during your workday. Your scope will be limited to the psychiatric assessment and treatment of patients engaged in a formal addiction treatment program. All patients are managed collaboratively with our team of Addiction Medicine Physicians, counselors, and psychotherapists in a high-quality, patient-centred environment . Experience and/or training in addictions psychiatry is an asset but not a requirement, as our collaborative team can provide guidance and mentorship in addiction medicine. Duties include: - Conducting virtual psychiatric assessments - Developing treatment and care plans - Prescribing medication(s) where appropriate - Supporting patients with substance use and concurrent disorders - Identifying safety concerns and referring to the ER when needed - Collaborating with other healthcare professionals - Maintaining appropriate clinical documentation and standards of care We are looking for a licensed psychiatrist with: - Strong clinical judgment and excellent communication skills - A compassionate, patient-centred approach - Comfort providing care through a virtual platform - The ability to work independently while collaborating effectively with a broader clinical team About our clinic: Comprehensive Treatment Clinic (CTC) is a new kind of addictions clinic focused on whole-person care. We offer treatment for persons using all kinds of substances. Our services include medication, counseling, art groups, affordable psychotherapy, harm reduction supplies, and more. Contact us at admin@ctctoronto.com or 647-490-4008 for more information. Website: http://www.ctctoronto.com', '{"About":"our clinic: Comprehensive Treatment Clinic (CTC) is a new kind of addictions clinic focused on whole-person care. We offer treatment for persons using all kinds of substances. Our services include medication, counseling, art groups, affordable psychotherapy, harm reduction supplies, and more. Contact us at admin@ctctoronto.com or 647-490-4008 for more information. Website: http://www.ctctoronto.com"}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Part-Time Psychiatrist – (Virtual Consultations)","description":"Part-Time Psychiatrist – (Virtual Consultations) Flexible Remote Opportunity | Competitive Compensation Hybrid of OHIP + Stipend Our outpatient community Rapid Access Addiction Medicine (RAAM) clinic is actively seeking a psychiatrist to join our team on a part-time, virtual basis. This is an ideal opportunity for a psychiatrist who wants to fit meaningful, well-compensated clinical work into an existing schedule. We offer the flexibility to choose when to see patients . Since most patients are admitted to a residential treatment facility, consults can fit throughout your day (e.g., during a no-show to your regular practice), ensuring no lost income during your workday. Your scope will be limited to the psychiatric assessment and treatment of patients engaged in a formal addiction treatment program. All patients are managed collaboratively with our team of Addiction Medicine Physicians, counselors, and psychotherapists in a high-quality, patient-centred environment . Experience and/or training in addictions psychiatry is an asset but not a requirement, as our collaborative team can provide guidance and mentorship in addiction medicine. Duties include: - Conducting virtual psychiatric assessments - Developing treatment and care plans - Prescribing medication(s) where appropriate - Supporting patients with substance use and concurrent disorders - Identifying safety concerns and referring to the ER when needed - Collaborating with other healthcare professionals - Maintaining appropriate clinical documentation and standards of care We are looking for a licensed psychiatrist with: - Strong clinical judgment and excellent communication skills - A compassionate, patient-centred approach - Comfort providing care through a virtual platform - The ability to work independently while collaborating effectively with a broader clinical team About our clinic: Comprehensive Treatment Clinic (CTC) is a new kind of addictions clinic focused on whole-person care. We offer treatment for persons using all kinds of substances. Our services include medication, counseling, art groups, affordable psychotherapy, harm reduction supplies, and more. Contact us at admin@ctctoronto.com or 647-490-4008 for more information. Website: http://www.ctctoronto.com","datePosted":"2026-08-20T00:00:00.000Z","validThrough":"2026-11-18T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Comprehensive Treatment Clinic"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"1154 Danforth Avenue","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M4J 1M3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a87ddd881b073648d717deb"}}'::jsonb, '2026-10-04T05:15:41.590Z'
)
