INSERT INTO jobs (
  job_id, url, title, specialty, employment_type, company, city, province, street_address, location_formatted, latitude, longitude, distance_from_toronto_km, compensation_raw, pay_rate_type, salary_min, salary_max, salary_avg, annualized_salary, physician_split_pct, clinic_split_pct, signing_bonus, relocation_bonus, accommodations_allowance, travel_allowance, is_hospital, requires_emr, requires_cfpc, requires_cpso, is_application_gated, gate_message, posted_date, closing_date, start_date, valid_through, is_expired, contact_emails, description_summary, full_description_text, structured_sections, external_links, raw_json_ld, scraped_at
) VALUES (
  '6a59b92edf36206c309880db', 'https://physiciancareers.ca/jobs/psychiatrist-part-time-virtual-ketamine-assisted-psychotherapy-kap-6a59b92edf36206c309880db', 'Psychiatrist (Part-time + Virtual) – Ketamine-Assisted Psychotherapy (KAP)', 'Psychiatry', 'part-time', 'Field Trip Health', 'downtown toronto', 'ON', '30 Duncan Street', 'Old Toronto, ON', 43.6532, -79.3832, 0, NULL, 'unspecified', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, FALSE, FALSE, FALSE, FALSE, FALSE, NULL, '2026-07-16', '2026-10-14', '2026-10-14', '2026-10-14', FALSE, '["adamblackman@fieldtriphealth.ca"]'::jsonb, '', 'Field Trip Health is expanding its medical team across Ontario, British Columbia, and Quebec, and we’re seeking psychiatrists who want to be part of one of North America’s most experienced and outcomes-informed KAP programs. KAP offers patients a powerful opportunity for meaningful therapeutic change — often helping individuals move forward when traditional treatments have plateaued. At Field Trip, psychiatrists are supported by a deeply collaborative care team and a clinical model built on safety, compassion, and evidence-based practice. Why Field Trip: Expertise you can trust: Field Trip is a leader in psychedelic-assisted therapies, with thousands of KAP sessions delivered and continuously refined care pathways. Training provided: Comprehensive onboarding and ongoing clinical support from experienced nurses, therapists, and medical leadership. Flexible, negotiable structure: Part-time, hybrid or virtual — tailored to your interests and availability with guaranteed sessional rates. No overhead costs: We provide full administrative, scheduling, and documentation support. Collaborative, values-aligned environment: Work alongside psychiatrists, nurses, and psychotherapists committed to clinical excellence and patient safety. Opportunities to shape the future of care: Contribute to evolving treatment models and practice-informed clinical research. To learn more, please contact Dr. Adam Blackman at adamblackman@fieldtriphealth.ca . Website: fieldtriphealth.ca', '{}'::jsonb, '[]'::jsonb, '{"@context":"https://schema.org","@type":"JobPosting","title":"Psychiatrist (Part-time + Virtual) – Ketamine-Assisted Psychotherapy (KAP)","description":"Field Trip Health is expanding its medical team across Ontario, British Columbia, and Quebec, and we’re seeking psychiatrists who want to be part of one of North America’s most experienced and outcomes-informed KAP programs. KAP offers patients a powerful opportunity for meaningful therapeutic change — often helping individuals move forward when traditional treatments have plateaued. At Field Trip, psychiatrists are supported by a deeply collaborative care team and a clinical model built on safety, compassion, and evidence-based practice. Why Field Trip: Expertise you can trust: Field Trip is a leader in psychedelic-assisted therapies, with thousands of KAP sessions delivered and continuously refined care pathways. Training provided: Comprehensive onboarding and ongoing clinical support from experienced nurses, therapists, and medical leadership. Flexible, negotiable structure: Part-time, hybrid or virtual — tailored to your interests and availability with guaranteed sessional rates. No overhead costs: We provide full administrative, scheduling, and documentation support. Collaborative, values-aligned environment: Work alongside psychiatrists, nurses, and psychotherapists committed to clinical excellence and patient safety. Opportunities to shape the future of care: Contribute to evolving treatment models and practice-informed clinical research. To learn more, please contact Dr. Adam Blackman at adamblackman@fieldtriphealth.ca . Website: fieldtriphealth.ca","datePosted":"2026-07-16T00:00:00.000Z","validThrough":"2026-10-14T00:00:00.000Z","hiringOrganization":{"@type":"Organization","name":"Field Trip Health"},"employmentType":"part-time","jobLocation":{"@type":"Place","address":{"@type":"PostalAddress","streetAddress":"30 Duncan Street","addressLocality":"Old Toronto","addressRegion":"ON","postalCode":"M5V 0H3","addressCountry":"CA"}},"identifier":{"@type":"PropertyValue","value":"6a59b92edf36206c309880db"}}'::jsonb, '2026-10-04T05:15:45.156Z'
)
